  "The default branch cannot be switched off. Make another branch the default first.": "ಡೀಫಾಲ್ಟ್ ಶಾಖೆಯನ್ನು ಆಫ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ. ಮೊದಲು ಇನ್ನೊಂದು ಶಾಖೆಯನ್ನು ಡೀಫಾಲ್ಟ್ ಮಾಡಿ.",
  "The website is the stock master again": "ವೆಬ್‌ಸೈಟ್ ಮತ್ತೆ ದಾಸ್ತಾನಿನ ಮುಖ್ಯ ಮೂಲವಾಗಿದೆ",
