  "When OFF (now), every order is handled by the default branch.": "ಆಫ್ ಆಗಿರುವಾಗ (ಈಗ), ಎಲ್ಲಾ ಆರ್ಡರ್‌ಗಳನ್ನು ಡೀಫಾಲ್ಟ್ ಶಾಖೆ ನಿರ್ವಹಿಸುತ್ತದೆ.",
  "When ON, each customer is served by the godown that lists their PIN code: they see that godown's stock, collect from it (or get its home delivery), and the order and its stock belong to that branch. PIN codes no godown lists go to the default branch.": "ಆನ್ ಆಗಿರುವಾಗ, ಪ್ರತಿ ಗ್ರಾಹಕರಿಗೆ ಅವರ PIN ಕೋಡ್ ಪಟ್ಟಿಯಲ್ಲಿರುವ ಗೋದಾಮು ಸೇವೆ ನೀಡುತ್ತದೆ: ಅವರು ಆ ಗೋದಾಮಿನ ದಾಸ್ತಾನು ನೋಡುತ್ತಾರೆ, ಅಲ್ಲಿಂದ ಪಡೆದುಕೊಳ್ಳುತ್ತಾರೆ (ಅಥವಾ ಅದರ ಮನೆ ಡೆಲಿವರಿ ಪಡೆಯುತ್ತಾರೆ), ಮತ್ತು ಆರ್ಡರ್ ಹಾಗೂ ಅದರ ದಾಸ್ತಾನು ಆ ಶಾಖೆಗೆ ಸೇರುತ್ತದೆ. ಯಾವ ಗೋದಾಮಿನ ಪಟ್ಟಿಯಲ್ಲೂ ಇಲ್ಲದ PIN ಕೋಡ್‌ಗಳು ಡೀಫಾಲ್ಟ್ ಶಾಖೆಗೆ ಹೋಗುತ್ತವೆ.",
