  "Use this when a customer asks to see or delete the information we hold on them.": "ಗ್ರಾಹಕರು ತಮ್ಮ ಬಗ್ಗೆ ನಮ್ಮಲ್ಲಿರುವ ಮಾಹಿತಿಯನ್ನು ನೋಡಲು ಅಥವಾ ಅಳಿಸಲು ಕೇಳಿದಾಗ ಇದನ್ನು ಬಳಸಿ.",
  "Download all their information": "ಅವರ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ",
  "Preparing the file…": "ಫೈಲ್ ಸಿದ್ಧವಾಗುತ್ತಿದೆ…",
  "Delete their information": "ಅವರ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸಿ",
  "The Excel file holds their profile, saved addresses with map positions, orders, payments, enquiries, reviews, returns and notifications.": "Excel ಫೈಲ್‌ನಲ್ಲಿ ಅವರ ಪ್ರೊಫೈಲ್, ನಕ್ಷೆ ಸ್ಥಾನಗಳೊಂದಿಗೆ ಉಳಿಸಿದ ವಿಳಾಸಗಳು, ಆರ್ಡರ್‌ಗಳು, ಪಾವತಿಗಳು, ವಿಚಾರಣೆಗಳು, ವಿಮರ್ಶೆಗಳು, ಹಿಂತಿರುಗಿಸುವಿಕೆಗಳು ಮತ್ತು ಸೂಚನೆಗಳು ಇರುತ್ತವೆ.",
  "Zoho is not changed.": "Zoho ಬದಲಾಗುವುದಿಲ್ಲ.",
  "Zoho keeps its own copy of any contact, sales orders and invoices it has for this customer, and the admin panel's Zoho sales order list shows them again when it next refreshes.": "Zoho ಈ ಗ್ರಾಹಕರ ಬಗ್ಗೆ ಹೊಂದಿರುವ ಸಂಪರ್ಕ, ಮಾರಾಟ ಆರ್ಡರ್‌ಗಳು ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳ ತನ್ನದೇ ಪ್ರತಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ, ಮತ್ತು ನಿರ್ವಾಹಕ ಫಲಕದ Zoho ಮಾರಾಟ ಆರ್ಡರ್ ಪಟ್ಟಿ ಮುಂದಿನ ರಿಫ್ರೆಶ್‌ನಲ್ಲಿ ಅವುಗಳನ್ನು ಮತ್ತೆ ತೋರಿಸುತ್ತದೆ.",
  "Zoho contact:": "Zoho ಸಂಪರ್ಕ:",
  "This customer's information has been deleted, but their login could not be removed.": "ಈ ಗ್ರಾಹಕರ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸಲಾಗಿದೆ, ಆದರೆ ಅವರ ಲಾಗಿನ್ ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Try removing the login again": "ಲಾಗಿನ್ ತೆಗೆದುಹಾಕಲು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
  "Removing…": "ತೆಗೆದುಹಾಕಲಾಗುತ್ತಿದೆ…",
  "The file has been downloaded": "ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಆಗಿದೆ",
  "Could not download the information": "ಮಾಹಿತಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "The customer's login has been removed": "ಗ್ರಾಹಕರ ಲಾಗಿನ್ ತೆಗೆದುಹಾಕಲಾಗಿದೆ",
  "Their login could not be removed": "ಅವರ ಲಾಗಿನ್ ತೆಗೆದುಹಾಕಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "By": "ಯಾರಿಂದ",
  "No information requests yet": "ಇನ್ನೂ ಮಾಹಿತಿ ವಿನಂತಿಗಳಿಲ್ಲ",
  "Information downloaded": "ಮಾಹಿತಿ ಡೌನ್‌ಲೋಡ್ ಮಾಡಲಾಗಿದೆ",
  "Information deleted": "ಮಾಹಿತಿ ಅಳಿಸಲಾಗಿದೆ",
  "Information deleted, login still to remove": "ಮಾಹಿತಿ ಅಳಿಸಲಾಗಿದೆ, ಲಾಗಿನ್ ಇನ್ನೂ ತೆಗೆದುಹಾಕಬೇಕಿದೆ",
  "The record of information requests could not be loaded.": "ಮಾಹಿತಿ ವಿನಂತಿಗಳ ದಾಖಲೆಯನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
  "Delete this customer's information?": "ಈ ಗ್ರಾಹಕರ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸಬೇಕೇ?",
  "Checking what can be deleted…": "ಏನನ್ನು ಅಳಿಸಬಹುದು ಎಂದು ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "Could not check this customer:": "ಈ ಗ್ರಾಹಕರನ್ನು ಪರಿಶೀಲಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ:",
  "This cannot be deleted yet": "ಇದನ್ನು ಇನ್ನೂ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "This customer cannot be deleted yet.": "ಈ ಗ್ರಾಹಕರನ್ನು ಇನ್ನೂ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "This person also has a seller, partner, staff or admin login. Those have their own records, so they cannot be deleted from here.": "ಈ ವ್ಯಕ್ತಿಗೆ ಮಾರಾಟಗಾರ, ಪಾಲುದಾರ, ಸಿಬ್ಬಂದಿ ಅಥವಾ ನಿರ್ವಾಹಕ ಲಾಗಿನ್ ಕೂಡ ಇದೆ. ಅವುಗಳಿಗೆ ಪ್ರತ್ಯೇಕ ದಾಖಲೆಗಳಿವೆ, ಆದ್ದರಿಂದ ಇಲ್ಲಿಂದ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "These orders are still open. Finish or cancel them first.": "ಈ ಆರ್ಡರ್‌ಗಳು ಇನ್ನೂ ತೆರೆದಿವೆ. ಮೊದಲು ಅವುಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ ಅಥವಾ ರದ್ದುಗೊಳಿಸಿ.",
  "These orders were delivered but are not fully paid. Record the payment first.": "ಈ ಆರ್ಡರ್‌ಗಳು ತಲುಪಿವೆ ಆದರೆ ಪೂರ್ಣ ಪಾವತಿಯಾಗಿಲ್ಲ. ಮೊದಲು ಪಾವತಿಯನ್ನು ದಾಖಲಿಸಿ.",
  "These orders were cancelled with money not refunded. Refund it first.": "ಈ ಆರ್ಡರ್‌ಗಳು ರದ್ದಾಗಿವೆ, ಆದರೆ ಹಣ ಮರುಪಾವತಿಯಾಗಿಲ್ಲ. ಮೊದಲು ಮರುಪಾವತಿ ಮಾಡಿ.",
  "These orders have a return or refund still open. Close it first.": "ಈ ಆರ್ಡರ್‌ಗಳ ಹಿಂತಿರುಗಿಸುವಿಕೆ ಅಥವಾ ಮರುಪಾವತಿ ಇನ್ನೂ ಬಾಕಿ ಇದೆ. ಮೊದಲು ಅದನ್ನು ಮುಗಿಸಿ.",
  "These orders have a payment reference still open. Close it in UPI & Bank Payments first.": "ಈ ಆರ್ಡರ್‌ಗಳ ಪಾವತಿ ಉಲ್ಲೇಖ ಇನ್ನೂ ಬಾಕಿ ಇದೆ. ಮೊದಲು UPI ಮತ್ತು ಬ್ಯಾಂಕ್ ಪಾವತಿಗಳಲ್ಲಿ ಅದನ್ನು ಮುಗಿಸಿ.",
  "These orders have money in the bank account still to be sorted out. Refund it or place the order, then mark it settled.": "ಈ ಆರ್ಡರ್‌ಗಳ ಹಣ ಬ್ಯಾಂಕ್ ಖಾತೆಯಲ್ಲಿದೆ, ಅದನ್ನು ಇನ್ನೂ ಇತ್ಯರ್ಥಪಡಿಸಬೇಕಿದೆ. ಮರುಪಾವತಿ ಮಾಡಿ ಅಥವಾ ಆರ್ಡರ್ ಮಾಡಿ, ನಂತರ ಇತ್ಯರ್ಥವಾಗಿದೆ ಎಂದು ಗುರುತಿಸಿ.",
  "This customer is being sent to Zoho right now. Try again in a minute.": "ಈ ಗ್ರಾಹಕರ ಮಾಹಿತಿ ಈಗ Zoho ಗೆ ಹೋಗುತ್ತಿದೆ. ಒಂದು ನಿಮಿಷದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "These orders are still going to Zoho or need a review in Zoho Sync. Clear that first.": "ಈ ಆರ್ಡರ್‌ಗಳು ಇನ್ನೂ Zoho ಗೆ ಹೋಗುತ್ತಿವೆ ಅಥವಾ Zoho Sync ನಲ್ಲಿ ಪರಿಶೀಲನೆ ಬೇಕಾಗಿದೆ. ಮೊದಲು ಅದನ್ನು ಸರಿಪಡಿಸಿ.",
  "These delivered orders have not reached Zoho yet. Send them first, so the sales records are complete.": "ಈ ತಲುಪಿದ ಆರ್ಡರ್‌ಗಳು ಇನ್ನೂ Zoho ತಲುಪಿಲ್ಲ. ಮಾರಾಟ ದಾಖಲೆಗಳು ಪೂರ್ಣವಾಗಲು ಮೊದಲು ಅವುಗಳನ್ನು ಕಳುಹಿಸಿ.",
  "Removed for good": "ಶಾಶ್ವತವಾಗಿ ತೆಗೆದುಹಾಕಲಾಗುವುದು",
