  "Login and profile": "ಲಾಗಿನ್ ಮತ್ತು ಪ್ರೊಫೈಲ್",
  "Saved addresses and map positions": "ಉಳಿಸಿದ ವಿಳಾಸಗಳು ಮತ್ತು ನಕ್ಷೆ ಸ್ಥಾನಗಳು",
  "Preferences": "ಆದ್ಯತೆಗಳು",
