  "Admin notes about them": "ಅವರ ಬಗ್ಗೆ ನಿರ್ವಾಹಕರ ಟಿಪ್ಪಣಿಗಳು",
  "Seller applications": "ಮಾರಾಟಗಾರರ ಅರ್ಜಿಗಳು",
  "Uploaded seller documents": "ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಮಾರಾಟಗಾರರ ದಾಖಲೆಗಳು",
  "Unpaid orders: name, phone, GSTIN and address cleared": "ಪಾವತಿಯಾಗದ ಆರ್ಡರ್‌ಗಳು: ಹೆಸರು, ಫೋನ್, GSTIN ಮತ್ತು ವಿಳಾಸ ತೆಗೆಯಲಾಗುವುದು",
  "Paid, delivered or refunded orders, with name, address and GSTIN": "ಹೆಸರು, ವಿಳಾಸ ಮತ್ತು GSTIN ಸಹಿತ ಪಾವತಿಯಾದ, ತಲುಪಿದ ಅಥವಾ ಮರುಪಾವತಿಯಾದ ಆರ್ಡರ್‌ಗಳು",
  "Bank receipts, with the payer's name": "ಪಾವತಿದಾರರ ಹೆಸರು ಸಹಿತ ಬ್ಯಾಂಕ್ ರಶೀದಿಗಳು",
