  "Other enquiries that use a phone or email from their profile or orders: {0}. We can't tell they are theirs, so they stay. Check them in Admin > Enquiries.": "ಅವರ ಪ್ರೊಫೈಲ್ ಅಥವಾ ಆರ್ಡರ್‌ಗಳಲ್ಲಿನ ಫೋನ್ ಅಥವಾ ಇಮೇಲ್ ಬಳಸುವ ಇತರ ವಿಚಾರಣೆಗಳು: {0}. ಅವು ಅವರದೇ ಎಂದು ಹೇಳಲು ಸಾಧ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ಅವು ಉಳಿಯುತ್ತವೆ. ನಿರ್ವಾಹಕ > ವಿಚಾರಣೆಗಳಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.",
  "No sales records to keep.": "ಉಳಿಸಿಕೊಳ್ಳಲು ಯಾವುದೇ ಮಾರಾಟ ದಾಖಲೆಗಳಿಲ್ಲ.",
  "Sales records may have to be kept by law. Phone and email come off them. They stay until the owner sets an end date.": "ಮಾರಾಟ ದಾಖಲೆಗಳನ್ನು ಕಾನೂನಿನ ಪ್ರಕಾರ ಇಟ್ಟುಕೊಳ್ಳಬೇಕಾಗಬಹುದು. ಅವುಗಳಿಂದ ಫೋನ್ ಮತ್ತು ಇಮೇಲ್ ತೆಗೆಯಲಾಗುವುದು. ಮಾಲೀಕರು ಅಂತಿಮ ದಿನಾಂಕ ನಿಗದಿಪಡಿಸುವವರೆಗೆ ಅವು ಉಳಿಯುತ್ತವೆ.",
