  "Adds the struck-through MRP, “% off” badge and “Save ₹N” to product cards, the product page, search and the cart. Each product's Pricing Display Mode still applies.": "ಉತ್ಪನ್ನ ಕಾರ್ಡ್‌ಗಳು, ಉತ್ಪನ್ನ ಪುಟ, ಹುಡುಕಾಟ ಮತ್ತು ಕಾರ್ಟ್‌ನಲ್ಲಿ ಹೊಡೆದುಹಾಕಿದ MRP, “% ರಿಯಾಯಿತಿ” ಬ್ಯಾಡ್ಜ್ ಮತ್ತು “₹N ಉಳಿಸಿ” ಸೇರಿಸುತ್ತದೆ. ಪ್ರತಿ ಉತ್ಪನ್ನದ ಬೆಲೆ ಪ್ರದರ್ಶನ ವಿಧಾನ ಹಾಗೆಯೇ ಅನ್ವಯಿಸುತ್ತದೆ.",
  "Advance on Order": "ಆರ್ಡರ್ ಮೇಲೆ ಮುಂಗಡ",
  "Advance payment (%)": "ಮುಂಗಡ ಪಾವತಿ (%)",
  "An MFA enrollment and challenge flow is not connected, so this app does not require a second factor.": "MFA ನೋಂದಣಿ ಮತ್ತು ಪರಿಶೀಲನಾ ವ್ಯವಸ್ಥೆ ಜೋಡಣೆಯಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ಈ ಆ್ಯಪ್ ಎರಡನೇ ಹಂತದ ಪರಿಶೀಲನೆ ಕೇಳುವುದಿಲ್ಲ.",
  "Applied to invoice downloads in customer accounts.": "ಗ್ರಾಹಕರ ಖಾತೆಗಳಲ್ಲಿನ ಇನ್‌ವಾಯ್ಸ್ ಡೌನ್‌ಲೋಡ್‌ಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ.",
  "Apply GST defaults to new products": "ಹೊಸ ಉತ್ಪನ್ನಗಳಿಗೆ ಡೀಫಾಲ್ಟ್ GST ಅನ್ವಯಿಸಿ",
