  "Cash on Delivery (Disabled)": "ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿ (ನಿಷ್ಕ್ರಿಯ)",
  "Cash on delivery is permanently disabled": "ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿಯನ್ನು ಶಾಶ್ವತವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ",
  "Cash on delivery is permanently disabled across the platform. All commodity and marketplace orders require online payment (UPI, Cards, Net Banking).": "ಇಡೀ ವೇದಿಕೆಯಲ್ಲಿ ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿಯನ್ನು ಶಾಶ್ವತವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. ಎಲ್ಲಾ ಸರಕು ಮತ್ತು ಮಾರುಕಟ್ಟೆ ಆರ್ಡರ್‌ಗಳಿಗೆ ಆನ್‌ಲೈನ್ ಪಾವತಿ (UPI, ಕಾರ್ಡ್‌ಗಳು, ನೆಟ್ ಬ್ಯಾಂಕಿಂಗ್) ಅಗತ್ಯ.",
