  "Godowns, the PIN codes they serve, pickup and home delivery are now managed per branch.": "ಗೋದಾಮುಗಳು, ಅವು ಸೇವೆ ನೀಡುವ PIN ಕೋಡ್‌ಗಳು, ಪಿಕಪ್ ಮತ್ತು ಮನೆ ಡೆಲಿವರಿಯನ್ನು ಈಗ ಪ್ರತಿ ಶಾಖೆಯಲ್ಲೇ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ.",
  "GST on New Products": "ಹೊಸ ಉತ್ಪನ್ನಗಳ ಮೇಲೆ GST",
