  "Needs a sales-order custom field in Zoho: label \"Order Channel\" (API name cf_order_channel). New orders are marked automatically.": "Zoho ದಲ್ಲಿ ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಕಸ್ಟಮ್ ಫೀಲ್ಡ್ ಬೇಕು: ಲೇಬಲ್ \"Order Channel\" (API ಹೆಸರು cf_order_channel). ಹೊಸ ಆರ್ಡರ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಗುರುತಿಸಲಾಗುತ್ತದೆ.",
