  "Shows how Zoho labels the channel on a Grain Bazar order and on a Zoho Commerce order. Nothing is changed.": "Grain Bazar ಆರ್ಡರ್ ಮತ್ತು Zoho Commerce ಆರ್ಡರ್‌ನಲ್ಲಿ Zoho ಚಾನೆಲ್ ಅನ್ನು ಹೇಗೆ ಗುರುತಿಸುತ್ತದೆ ಎಂದು ತೋರಿಸುತ್ತದೆ. ಏನನ್ನೂ ಬದಲಾಯಿಸುವುದಿಲ್ಲ.",
