  "Review each failed record details below, or click Retry all failed to requeue and push them to Zoho.": "ಕೆಳಗಿನ ಪ್ರತಿ ವಿಫಲ ದಾಖಲೆಯ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಅಥವಾ ಅವನ್ನು ಮತ್ತೆ ಸರದಿಗೆ ಸೇರಿಸಿ Zoho ಗೆ ಕಳುಹಿಸಲು ವಿಫಲವಾದ ಎಲ್ಲವನ್ನೂ ಮರುಪ್ರಯತ್ನಿಸಿ ಕ್ಲಿಕ್ ಮಾಡಿ.",
  "Review Zoho app settings and server configuration, then try again.": "Zoho ಆ್ಯಪ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಸರ್ವರ್ ಸಂರಚನೆಯನ್ನು ಪರಿಶೀಲಿಸಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
