  "scans all past local records and queues any not yet synced to Zoho.": "ಹಿಂದಿನ ಎಲ್ಲಾ ಸ್ಥಳೀಯ ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಇನ್ನೂ Zoho ಗೆ ಸಿಂಕ್ ಆಗದವನ್ನು ಸರದಿಗೆ ಸೇರಿಸುತ್ತದೆ.",
