  "This coupon is unavailable, below its minimum order, or has reached its per-customer limit.": "ಈ ಕೂಪನ್ ಲಭ್ಯವಿಲ್ಲ, ಕನಿಷ್ಠ ಆರ್ಡರ್ ಮೊತ್ತಕ್ಕಿಂತ ಕಡಿಮೆ ಇದೆ, ಅಥವಾ ಪ್ರತಿ ಗ್ರಾಹಕರ ಮಿತಿ ತಲುಪಿದೆ.",
  "UPI with no extra charges": "ಯಾವುದೇ ಹೆಚ್ಚುವರಿ ಶುಲ್ಕವಿಲ್ಲದೆ UPI",
