  "PIN {0} is served by the {1} godown. Prices and stock will change to that godown's.": "PIN {0} ಗೆ {1} ಗೋದಾಮು ಸೇವೆ ನೀಡುತ್ತದೆ. ಬೆಲೆಗಳು ಮತ್ತು ದಾಸ್ತಾನು ಆ ಗೋದಾಮಿನದಕ್ಕೆ ಬದಲಾಗುತ್ತವೆ.",
  "We don't deliver to PIN {0} yet. You can save it, but orders can't be placed for it.": "PIN {0} ಗೆ ನಾವು ಇನ್ನೂ ಡೆಲಿವರಿ ಮಾಡುವುದಿಲ್ಲ. ಇದನ್ನು ಉಳಿಸಬಹುದು, ಆದರೆ ಇದಕ್ಕೆ ಆರ್ಡರ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Your total changed from {0} to {1}": "ನಿಮ್ಮ ಒಟ್ಟು ಮೊತ್ತ {0} ರಿಂದ {1} ಕ್ಕೆ ಬದಲಾಗಿದೆ",
  "Your total stays {0}": "ನಿಮ್ಮ ಒಟ್ಟು ಮೊತ್ತ {0} ಆಗಿಯೇ ಇರುತ್ತದೆ",
