  "{0}: out of stock at the {1} godown": "{0}: {1} ಗೋದಾಮಿನಲ್ಲಿ ದಾಸ್ತಾನು ಇಲ್ಲ",
  "{0}: only {1} available at the {2} godown, you have {3}": "{0}: {2} ಗೋದಾಮಿನಲ್ಲಿ {1} ಮಾತ್ರ ಲಭ್ಯ, ನೀವು {3} ಆಯ್ಕೆ ಮಾಡಿದ್ದೀರಿ",
