  "No item in your cart is sold at the {0} godown.": "ನಿಮ್ಮ ಕಾರ್ಟ್‌ನಲ್ಲಿರುವ ಯಾವ ವಸ್ತುವೂ {0} ಗೋದಾಮಿನಲ್ಲಿ ಮಾರಾಟವಾಗುವುದಿಲ್ಲ.",
  "Updating prices…": "ಬೆಲೆಗಳನ್ನು ನವೀಕರಿಸಲಾಗುತ್ತಿದೆ…",
  "Address on this checkout": "ಈ ಚೆಕ್‌ಔಟ್‌ನ ವಿಳಾಸ",
  "Address on this order": "ಈ ಆರ್ಡರ್‌ನ ವಿಳಾಸ",
  "This order is placed, so its address can't be changed here. If it is wrong, call us on +91 98459 66288.": "ಈ ಆರ್ಡರ್ ಮಾಡಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಇದರ ವಿಳಾಸವನ್ನು ಇಲ್ಲಿ ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ವಿಳಾಸ ತಪ್ಪಾಗಿದ್ದರೆ +91 98459 66288 ಗೆ ಕರೆ ಮಾಡಿ.",
  "We are checking your payment for this checkout, so its address can't be changed now. If it is wrong, call us on +91 98459 66288.": "ಈ ಚೆಕ್‌ಔಟ್‌ನ ಪಾವತಿಯನ್ನು ನಾವು ಪರಿಶೀಲಿಸುತ್ತಿದ್ದೇವೆ, ಆದ್ದರಿಂದ ಇದರ ವಿಳಾಸವನ್ನು ಈಗ ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ವಿಳಾಸ ತಪ್ಪಾಗಿದ್ದರೆ +91 98459 66288 ಗೆ ಕರೆ ಮಾಡಿ.",
  "This address can't be changed now: your prices and stock are held at the {0} godown for it, and the payment is for this exact amount. If you have not paid yet and need another address, cancel this payment, press Reorder and start again. If you have already paid, do not cancel: call us on +91 98459 66288.": "ಈ ವಿಳಾಸವನ್ನು ಈಗ ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ: ಇದಕ್ಕಾಗಿ ನಿಮ್ಮ ಬೆಲೆಗಳು ಮತ್ತು ದಾಸ್ತಾನನ್ನು {0} ಗೋದಾಮಿನಲ್ಲಿ ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ, ಮತ್ತು ಪಾವತಿ ಇದೇ ನಿಖರ ಮೊತ್ತಕ್ಕೆ ಇದೆ. ನೀವು ಇನ್ನೂ ಪಾವತಿಸಿಲ್ಲದಿದ್ದರೆ ಮತ್ತು ಬೇರೆ ವಿಳಾಸ ಬೇಕಿದ್ದರೆ, ಈ ಪಾವತಿಯನ್ನು ರದ್ದುಮಾಡಿ, \"ಮತ್ತೆ ಆರ್ಡರ್ ಮಾಡಿ\" ಒತ್ತಿ ಮತ್ತೆ ಪ್ರಾರಂಭಿಸಿ. ಈಗಾಗಲೇ ಪಾವತಿಸಿದ್ದರೆ ರದ್ದುಮಾಡಬೇಡಿ: +91 98459 66288 ಗೆ ಕರೆ ಮಾಡಿ.",
