  "Paid revenue uses each order line’s captured price. Available earnings include only paid, delivered orders after commission and payout reservations.": "ಪಾವತಿಯಾದ ಆದಾಯವು ಪ್ರತಿ ಆರ್ಡರ್ ಸಾಲಿನಲ್ಲಿ ದಾಖಲಾದ ಬೆಲೆಯನ್ನು ಬಳಸುತ್ತದೆ. ಲಭ್ಯವಿರುವ ಆದಾಯದಲ್ಲಿ ಕಮಿಷನ್ ಮತ್ತು ಪಾವತಿ ಮೀಸಲುಗಳನ್ನು ಕಳೆದ ನಂತರ, ಪಾವತಿಯಾದ ಮತ್ತು ತಲುಪಿಸಿದ ಆರ್ಡರ್‌ಗಳು ಮಾತ್ರ ಸೇರಿರುತ್ತವೆ.",
