  "Please complete the payment. We can issue your delivery note and release your order only after the full invoice amount is paid.": "ದಯವಿಟ್ಟು ಪಾವತಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ. ಇನ್‌ವಾಯ್ಸ್‌ನ ಪೂರ್ಣ ಮೊತ್ತ ಪಾವತಿಯಾದ ನಂತರವೇ ನಾವು ನಿಮ್ಮ ಡೆಲಿವರಿ ನೋಟ್ ನೀಡಿ ಆರ್ಡರ್ ಬಿಡುಗಡೆ ಮಾಡಬಹುದು.",
  "Please call us about this order's payment": "ಈ ಆರ್ಡರ್‌ನ ಪಾವತಿ ಬಗ್ಗೆ ದಯವಿಟ್ಟು ನಮಗೆ ಕರೆ ಮಾಡಿ",
  "Our payment records for this order need checking. Please do not pay again before speaking to us.": "ಈ ಆರ್ಡರ್‌ನ ಪಾವತಿ ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಬೇಕಾಗಿದೆ. ನಮ್ಮೊಂದಿಗೆ ಮಾತನಾಡುವ ಮೊದಲು ದಯವಿಟ್ಟು ಮತ್ತೆ ಪಾವತಿಸಬೇಡಿ.",
  "Need help? Call +91 98459 66288": "ಸಹಾಯ ಬೇಕೇ? +91 98459 66288 ಗೆ ಕರೆ ಮಾಡಿ",
  "Its only orders were cancelled or expired, and every unit came back. Deleting it removes the batch record, and those orders no longer show this batch number. Stock does not change, here or in Zoho.": "ಇದರ ಆರ್ಡರ್‌ಗಳು ರದ್ದಾಗಿವೆ ಅಥವಾ ಅವಧಿ ಮುಗಿದಿವೆ, ಮತ್ತು ಎಲ್ಲಾ ಘಟಕಗಳು ಹಿಂತಿರುಗಿವೆ. ಅಳಿಸಿದರೆ ಬ್ಯಾಚ್ ದಾಖಲೆ ಹೋಗುತ್ತದೆ, ಮತ್ತು ಆ ಆರ್ಡರ್‌ಗಳಲ್ಲಿ ಈ ಬ್ಯಾಚ್ ಸಂಖ್ಯೆ ಕಾಣುವುದಿಲ್ಲ. ಇಲ್ಲಿ ಅಥವಾ Zoho ದಲ್ಲಿ ಸ್ಟಾಕ್ ಬದಲಾಗುವುದಿಲ್ಲ.",
  "Delete order": "ಆರ್ಡರ್ ಅಳಿಸಿ",
  "Delete order {0}?": "{0} ಆರ್ಡರ್ ಅಳಿಸಬೇಕೆ?",
  "Order {0} deleted": "{0} ಆರ್ಡರ್ ಅಳಿಸಲಾಗಿದೆ",
  "Reason (optional)": "ಕಾರಣ (ಐಚ್ಛಿಕ)",
  "Checking whether it can be deleted…": "ಅಳಿಸಬಹುದೇ ಎಂದು ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "Nothing was paid, sent to Zoho or delivered. Deleting removes the order and its items for good. Zoho and stock are not touched, and a record of who deleted it is kept.": "ಏನನ್ನೂ ಪಾವತಿಸಿಲ್ಲ, Zoho ಗೆ ಕಳುಹಿಸಿಲ್ಲ ಅಥವಾ ತಲುಪಿಸಿಲ್ಲ. ಅಳಿಸಿದರೆ ಆರ್ಡರ್ ಮತ್ತು ಅದರ ವಸ್ತುಗಳು ಶಾಶ್ವತವಾಗಿ ಹೋಗುತ್ತವೆ. Zoho ಮತ್ತು ಸ್ಟಾಕ್ ಬದಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ಯಾರು ಅಳಿಸಿದರು ಎಂಬ ದಾಖಲೆ ಉಳಿಯುತ್ತದೆ.",
  "Nothing changed in Zoho or in stock. A record of the delete is kept.": "Zoho ಅಥವಾ ಸ್ಟಾಕ್‌ನಲ್ಲಿ ಏನೂ ಬದಲಾಗಿಲ್ಲ. ಅಳಿಸಿದ ದಾಖಲೆ ಉಳಿದಿದೆ.",
  "Could not delete the order": "ಆರ್ಡರ್ ಅಳಿಸಲು ಆಗಲಿಲ್ಲ",
  "Payment expired, cancelled": "ಪಾವತಿ ಅವಧಿ ಮುಗಿದಿದೆ, ರದ್ದಾಗಿದೆ",
  "Cancelled, not paid": "ರದ್ದಾಗಿದೆ, ಪಾವತಿಸಿಲ್ಲ",
  "Time ran out": "ಸಮಯ ಮುಗಿಯಿತು",
  "Customer left the checkout": "ಗ್ರಾಹಕರು ಚೆಕ್‌ಔಟ್ ಬಿಟ್ಟರು",
  "Ended by an admin": "ನಿರ್ವಾಹಕರು ಕೊನೆಗೊಳಿಸಿದರು",
  "None right now.": "ಈಗ ಯಾವುದೂ ಇಲ್ಲ.",
  "Ended without payment": "ಪಾವತಿ ಇಲ್ಲದೆ ಕೊನೆಗೊಂಡವು",
  "Checkouts whose payment window ran out, or that were ended. They are not orders and owe nothing. Delete one only when it is no longer wanted.": "ಪಾವತಿ ಅವಧಿ ಮುಗಿದ ಅಥವಾ ಕೊನೆಗೊಳಿಸಿದ ಚೆಕ್‌ಔಟ್‌ಗಳು. ಇವು ಆರ್ಡರ್‌ಗಳಲ್ಲ ಮತ್ತು ಯಾವುದೇ ಬಾಕಿ ಇಲ್ಲ. ಅಗತ್ಯವಿಲ್ಲದಿದ್ದಾಗ ಮಾತ್ರ ಅಳಿಸಿ.",
  "1 checkout ended without payment": "1 ಚೆಕ್‌ಔಟ್ ಪಾವತಿ ಇಲ್ಲದೆ ಕೊನೆಗೊಂಡಿದೆ",
  "{0} checkouts ended without payment": "{0} ಚೆಕ್‌ಔಟ್‌ಗಳು ಪಾವತಿ ಇಲ್ಲದೆ ಕೊನೆಗೊಂಡಿವೆ",
  "time up · check the bank": "ಸಮಯ ಮುಗಿದಿದೆ · ಬ್ಯಾಂಕ್ ಪರಿಶೀಲಿಸಿ",
  "This order no longer exists.": "ಈ ಆರ್ಡರ್ ಈಗ ಇಲ್ಲ.",
  "Only an order whose payment window ran out, or a cancelled order, can be deleted.": "ಪಾವತಿ ಅವಧಿ ಮುಗಿದ ಅಥವಾ ರದ್ದಾದ ಆರ್ಡರ್ ಮಾತ್ರ ಅಳಿಸಬಹುದು.",
  "Money was recorded on this order, so it stays for the accounts.": "ಈ ಆರ್ಡರ್‌ನಲ್ಲಿ ಹಣ ದಾಖಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಲೆಕ್ಕಕ್ಕಾಗಿ ಉಳಿಯುತ್ತದೆ.",
  "The customer sent a UTR for this order, so it stays. Check the bank for that transfer.": "ಗ್ರಾಹಕರು ಈ ಆರ್ಡರ್‌ಗೆ UTR ಕಳುಹಿಸಿದ್ದಾರೆ, ಆದ್ದರಿಂದ ಉಳಿಯುತ್ತದೆ. ಆ ವರ್ಗಾವಣೆಗಾಗಿ ಬ್ಯಾಂಕ್ ಪರಿಶೀಲಿಸಿ.",
  "A bank credit is linked to this order, so it stays for the accounts.": "ಈ ಆರ್ಡರ್‌ಗೆ ಬ್ಯಾಂಕ್ ಜಮೆ ಸಂಪರ್ಕಗೊಂಡಿದೆ, ಆದ್ದರಿಂದ ಲೆಕ್ಕಕ್ಕಾಗಿ ಉಳಿಯುತ್ತದೆ.",
  "This order was sent to Zoho, so it stays to match Zoho.": "ಈ ಆರ್ಡರ್ Zoho ಗೆ ಹೋಗಿದೆ, ಆದ್ದರಿಂದ Zoho ಗೆ ಹೊಂದುವಂತೆ ಉಳಿಯುತ್ತದೆ.",
  "An invoice exists for this order, so it stays.": "ಈ ಆರ್ಡರ್‌ಗೆ ಇನ್‌ವಾಯ್ಸ್ ಇದೆ, ಆದ್ದರಿಂದ ಉಳಿಯುತ್ತದೆ.",
  "A delivery note exists for this order, so it stays.": "ಈ ಆರ್ಡರ್‌ಗೆ ಡೆಲಿವರಿ ನೋಟ್ ಇದೆ, ಆದ್ದರಿಂದ ಉಳಿಯುತ್ತದೆ.",
  "A partner commission is recorded on this order, so it stays.": "ಈ ಆರ್ಡರ್‌ನಲ್ಲಿ ಪಾಲುದಾರರ ಕಮಿಷನ್ ದಾಖಲಾಗಿದೆ, ಆದ್ದರಿಂದ ಉಳಿಯುತ್ತದೆ.",
  "This order has a review or a return, so it stays.": "ಈ ಆರ್ಡರ್‌ಗೆ ವಿಮರ್ಶೆ ಅಥವಾ ಹಿಂತಿರುಗಿಸುವಿಕೆ ಇದೆ, ಆದ್ದರಿಂದ ಉಳಿಯುತ್ತದೆ.",
