  "TOTAL IN WORDS": "ಒಟ್ಟು ಮೊತ್ತ ಅಕ್ಷರಗಳಲ್ಲಿ",
  "Office copy: includes fulfilling vendor details. Do not share with the customer.": "ಕಚೇರಿ ಪ್ರತಿ: ಆರ್ಡರ್ ಪೂರೈಸುವ ಮಾರಾಟಗಾರರ ವಿವರಗಳನ್ನು ಒಳಗೊಂಡಿದೆ. ಗ್ರಾಹಕರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ.",
