  "Whether tax is payable under reverse charge - No": "ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಅಡಿಯಲ್ಲಿ ತೆರಿಗೆ ಪಾವತಿಸಬೇಕೇ - ಇಲ್ಲ",
