  "No registered customer account exists with this phone or email. Please register first.": "ಈ ಮೊಬೈಲ್ ಅಥವಾ ಇಮೇಲ್‌ನೊಂದಿಗೆ ಯಾವುದೇ ನೋಂದಾಯಿತ ಗ್ರಾಹಕ ಖಾತೆ ಇಲ್ಲ. ದಯವಿಟ್ಟು ಮೊದಲು ನೋಂದಾಯಿಸಿ.",
