  "{0} sent UTR {1} for {2} (Rs {3}). Match it in the bank account, then confirm in Admin > UPI Payments.": "{0} ಅವರು {2} ಗಾಗಿ UTR {1} ಕಳುಹಿಸಿದ್ದಾರೆ (Rs {3}). ಬ್ಯಾಂಕ್ ಖಾತೆಯಲ್ಲಿ ಹೊಂದಿಸಿ ನೋಡಿ, ನಂತರ ನಿರ್ವಾಹಕ > UPI ಪಾವತಿಗಳು ನಲ್ಲಿ ದೃಢೀಕರಿಸಿ.",
