  "Invoice {0} for order {1} is partly paid; ₹{2} is due.": "ಆರ್ಡರ್ {1} ರ ಇನ್‌ವಾಯ್ಸ್ {0} ಭಾಗಶಃ ಪಾವತಿಯಾಗಿದೆ; ₹{2} ಬಾಕಿ ಇದೆ.",
  "Invoice {0} for order {1} was {2} in Zoho Books. A new invoice will be issued after admin approval.": "ಆರ್ಡರ್ {1} ರ ಇನ್‌ವಾಯ್ಸ್ {0} Zoho Books ನಲ್ಲಿ {2}. ನಿರ್ವಾಹಕರ ಅನುಮೋದನೆಯ ನಂತರ ಹೊಸ ಇನ್‌ವಾಯ್ಸ್ ನೀಡಲಾಗುತ್ತದೆ.",
  "Invoice {0}{1} for order {2} is fully paid.": "ಆರ್ಡರ್ {2} ರ ಇನ್‌ವಾಯ್ಸ್ {0}{1} ಪೂರ್ತಿಯಾಗಿ ಪಾವತಿಯಾಗಿದೆ.",
  "Invoice {0}{1} was issued for order {2}.": "ಆರ್ಡರ್ {2} ಗಾಗಿ ಇನ್‌ವಾಯ್ಸ್ {0}{1} ನೀಡಲಾಗಿದೆ.",
  "Order {0} has no Zoho invoice. Approve a new invoice from the order page.": "ಆರ್ಡರ್ {0} ಗೆ Zoho ಇನ್‌ವಾಯ್ಸ್ ಇಲ್ಲ. ಆರ್ಡರ್ ಪುಟದಿಂದ ಹೊಸ ಇನ್‌ವಾಯ್ಸ್ ಅನುಮೋದಿಸಿ.",
  "Order {0} includes products assigned to your store.": "ಆರ್ಡರ್ {0} ನಲ್ಲಿ ನಿಮ್ಮ ಅಂಗಡಿಗೆ ಸೇರಿದ ಉತ್ಪನ್ನಗಳಿವೆ.",
  "Order {0} is now {1}.": "ಆರ್ಡರ್ {0} ಈಗ: {1}.",
  "Order {0} was placed for ₹{1}.": "₹{1} ಮೊತ್ತದ ಆರ್ಡರ್ {0} ಮಾಡಲಾಗಿದೆ.",
  "Order {0}: paid {1} of {2}; payment is {3}.": "ಆರ್ಡರ್ {0}: {2} ರಲ್ಲಿ {1} ಪಾವತಿಸಲಾಗಿದೆ; ಪಾವತಿ ಸ್ಥಿತಿ: {3}.",
  "Review {0} was reported by vendor {1}. Reason: {2}": "ವಿಮರ್ಶೆ {0} ಬಗ್ಗೆ ಮಾರಾಟಗಾರ {1} ದೂರು ನೀಡಿದ್ದಾರೆ. ಕಾರಣ: {2}",
  "The return for order {0} is {1} (refund: {2}).": "ಆರ್ಡರ್ {0} ರ ಹಿಂತಿರುಗಿಸುವಿಕೆ: {1} (ಮರುಪಾವತಿ: {2}).",
  "UTR {0} for order {1} could not be matched{2}. Open the order and send the correct UTR.": "ಆರ್ಡರ್ {1} ರ UTR {0} ಹೊಂದಿಕೆಯಾಗಲಿಲ್ಲ{2}. ಆರ್ಡರ್ ತೆರೆದು ಸರಿಯಾದ UTR ಕಳುಹಿಸಿ.",
  "We received Rs {0} for order {1} (UTR {2}). Thank you!": "ಆರ್ಡರ್ {1} ಗಾಗಿ Rs {0} ಸ್ವೀಕರಿಸಿದ್ದೇವೆ (UTR {2}). ಧನ್ಯವಾದಗಳು!",
  "Your order {0} has been received.": "ನಿಮ್ಮ ಆರ್ಡರ್ {0} ಸ್ವೀಕರಿಸಲಾಗಿದೆ.",
