  "(no GST bill)": "(GST ಬಿಲ್ ಇಲ್ಲ)",
  "You have selected a GST invoice. Please make the payment from your registered firm / business account.": "ನೀವು GST ಇನ್‌ವಾಯ್ಸ್ ಆಯ್ಕೆ ಮಾಡಿದ್ದೀರಿ. ದಯವಿಟ್ಟು ನಿಮ್ಮ ನೋಂದಾಯಿತ ಸಂಸ್ಥೆ / ವ್ಯವಹಾರದ ಖಾತೆಯಿಂದ ಪಾವತಿ ಮಾಡಿ.",
