  "Slides one after another at the top of the home page (videos play to the end). Best size 2100 × 900 (21:9); any size works: choose Fill or Whole picture.": "ಮುಖಪುಟದ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಒಂದರ ನಂತರ ಒಂದು ಸ್ಲೈಡ್ ಆಗುತ್ತವೆ (ವೀಡಿಯೊಗಳು ಕೊನೆಯವರೆಗೆ ಪ್ಲೇ ಆಗುತ್ತವೆ). ಉತ್ತಮ ಗಾತ್ರ 2100 × 900 (21:9); ಯಾವುದೇ ಗಾತ್ರ ಸರಿ: 'ಪೂರ್ಣ ತುಂಬು' ಅಥವಾ 'ಪೂರ್ಣ ಚಿತ್ರ' ಆರಿಸಿ.",
  "Beside the big banner on computers, and a moving strip under it on phones. Best size 1280 × 720 (16:9).": "ಕಂಪ್ಯೂಟರ್‌ಗಳಲ್ಲಿ ದೊಡ್ಡ ಬ್ಯಾನರ್‌ನ ಪಕ್ಕದಲ್ಲಿ, ಫೋನ್‌ಗಳಲ್ಲಿ ಅದರ ಕೆಳಗೆ ಚಲಿಸುವ ಪಟ್ಟಿಯಾಗಿ. ಉತ್ತಮ ಗಾತ್ರ 1280 × 720 (16:9).",
