  "Shami Sugar Mills": "Shami Sugar Mills",
  "Needs review": "ಪರಿಶೀಲನೆ ಬೇಕು",
  Complete: "ಪೂರ್ಣಗೊಂಡಿದೆ",
  "Unauthorized: No authorization header provided": "ಅನುಮತಿ ಇಲ್ಲ: ದಯವಿಟ್ಟು ಮತ್ತೆ ಲಾಗಿನ್ ಆಗಿ",
  "Zoho said: “": "Zoho ಹೇಳಿದ್ದು: “",
  "“Queue existing data”": "“Queue existing data”",
  "” Zoho must raise the organization's sales-order allowance, then click \"Retry\". \"Dismiss\" skips this order.": "” Zoho ಸಂಸ್ಥೆಯ ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಮಿತಿಯನ್ನು ಹೆಚ್ಚಿಸಬೇಕು, ನಂತರ \"Retry\" ಕ್ಲಿಕ್ ಮಾಡಿ. \"Dismiss\" ಈ ಆರ್ಡರ್ ಅನ್ನು ಬಿಟ್ಟುಬಿಡುತ್ತದೆ.",
  "Outbound writes can be pushed with \"Push pending to Zoho\" or processed every 15 minutes by the scheduled sync.": "ಹೊರಹೋಗುವ ಬದಲಾವಣೆಗಳನ್ನು \"Push pending to Zoho\" ಮೂಲಕ ಕಳುಹಿಸಬಹುದು, ಅಥವಾ ನಿಗದಿತ ಸಿಂಕ್ ಪ್ರತಿ 15 ನಿಮಿಷಕ್ಕೊಮ್ಮೆ ಕಳುಹಿಸುತ್ತದೆ.",
  "The scheduled sync checks supported linked-order shipment milestones every 15 minutes and applies eligible fulfillment changes to Grain Bazar orders. Imported Zoho sales order snapshots still need a manual \"Sync account data\" refresh.": "ನಿಗದಿತ ಸಿಂಕ್ ಪ್ರತಿ 15 ನಿಮಿಷಕ್ಕೊಮ್ಮೆ ಜೋಡಿಸಿದ ಆರ್ಡರ್‌ಗಳ ಸಾಗಣೆ ಹಂತಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಅರ್ಹ ಬದಲಾವಣೆಗಳನ್ನು Grain Bazar ಆರ್ಡರ್‌ಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಆಮದು ಮಾಡಿದ Zoho ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗಳಿಗೆ ಇನ್ನೂ ಕೈಯಾರೆ \"Sync account data\" ರಿಫ್ರೆಶ್ ಬೇಕು.",
  "Zoho refused to create these sales orders because the organization has used its sales-order allowance for this period. Re-authorizing does not change this; Zoho (billing or support) has to raise the allowance, or it resets at the start of the next period. Then click \"Retry\" on each order. You can also dismiss them so they no longer block your sync status.": "ಈ ಅವಧಿಯ ಸೇಲ್ಸ್ ಆರ್ಡರ್ ಮಿತಿ ಮುಗಿದಿರುವುದರಿಂದ Zoho ಈ ಸೇಲ್ಸ್ ಆರ್ಡರ್‌ಗಳನ್ನು ರಚಿಸಲು ನಿರಾಕರಿಸಿದೆ. ಮರು-ಅಧಿಕೃತಗೊಳಿಸುವುದರಿಂದ ಇದು ಬದಲಾಗುವುದಿಲ್ಲ; Zoho (ಬಿಲ್ಲಿಂಗ್ ಅಥವಾ ಬೆಂಬಲ) ಮಿತಿಯನ್ನು ಹೆಚ್ಚಿಸಬೇಕು, ಇಲ್ಲವೇ ಮುಂದಿನ ಅವಧಿಯ ಆರಂಭದಲ್ಲಿ ಅದು ಮರುಹೊಂದುತ್ತದೆ. ನಂತರ ಪ್ರತಿ ಆರ್ಡರ್‌ನಲ್ಲಿ \"Retry\" ಕ್ಲಿಕ್ ಮಾಡಿ. ಸಿಂಕ್ ಸ್ಥಿತಿಗೆ ಅಡ್ಡಿಯಾಗದಂತೆ ಅವುಗಳನ್ನು ವಜಾಗೊಳಿಸಲೂ ಬಹುದು.",
  // Godown employee attendance (31 Oct 2026)
