  "Count the packs on the godown floor and enter the number. Zoho and the website are updated at once.": "ಗೋದಾಮಿನಲ್ಲಿರುವ ಪ್ಯಾಕ್‌ಗಳನ್ನು ಎಣಿಸಿ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ. Zoho ಮತ್ತು ವೆಬ್‌ಸೈಟ್ ತಕ್ಷಣ ನವೀಕರಣಗೊಳ್ಳುತ್ತವೆ.",
  "No products found.": "ಯಾವುದೇ ಉತ್ಪನ್ನಗಳು ಸಿಗಲಿಲ್ಲ.",
  "in stock": "ದಾಸ್ತಾನಿನಲ್ಲಿ",
  "Recent stock updates at this godown": "ಈ ಗೋದಾಮಿನ ಇತ್ತೀಚಿನ ದಾಸ್ತಾನು ನವೀಕರಣಗಳು",
  "Big change": "ದೊಡ್ಡ ಬದಲಾವಣೆ",
  "Enter the counted quantity": "ಎಣಿಸಿದ ಪ್ರಮಾಣವನ್ನು ನಮೂದಿಸಿ",
  "Enter whole bags / packs": "ಪೂರ್ಣ ಚೀಲ / ಪ್ಯಾಕ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ",
  "The count can't be negative": "ಎಣಿಕೆ ಋಣಾತ್ಮಕವಾಗಿರಬಾರದು",
  "That count is too large": "ಆ ಎಣಿಕೆ ತುಂಬಾ ದೊಡ್ಡದು",
  "Stock updated": "ದಾಸ್ತಾನು ನವೀಕರಿಸಲಾಗಿದೆ",
  "Stock was not updated": "ದಾಸ್ತಾನು ನವೀಕರಿಸಲಾಗಿಲ್ಲ",
  "Stock updated in Zoho and on the website": "Zoho ಮತ್ತು ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ದಾಸ್ತಾನು ನವೀಕರಿಸಲಾಗಿದೆ",
  "Counted {0} (Zoho had {1}). Website stock now {2}.": "ಎಣಿಕೆ {0} (Zoho ದಲ್ಲಿ {1} ಇತ್ತು). ಈಗ ವೆಬ್‌ಸೈಟ್ ದಾಸ್ತಾನು {2}.",
  "Big change: head office will check it.": "ದೊಡ್ಡ ಬದಲಾವಣೆ: ಮುಖ್ಯ ಕಚೇರಿ ಇದನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.",
  "Counted quantity (packs on the floor)": "ಎಣಿಸಿದ ಪ್ರಮಾಣ (ಗೋದಾಮಿನಲ್ಲಿರುವ ಪ್ಯಾಕ್‌ಗಳು)",
  "Daily stock count": "ದೈನಂದಿನ ದಾಸ್ತಾನು ಎಣಿಕೆ",
