  "Save count": "ಎಣಿಕೆ ಉಳಿಸಿ",
  "Only active godown employees can update stock": "ಸಕ್ರಿಯ ಗೋದಾಮು ಸಿಬ್ಬಂದಿ ಮಾತ್ರ ದಾಸ್ತಾನು ನವೀಕರಿಸಬಹುದು",
  "Stock updates need Zoho as the stock master. Ask head office.": "ದಾಸ್ತಾನು ನವೀಕರಣಕ್ಕೆ Zoho ದಾಸ್ತಾನು ಮಾಸ್ಟರ್ ಆಗಿರಬೇಕು. ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "Your godown is not linked to a Zoho location. Ask head office.": "ನಿಮ್ಮ ಗೋದಾಮು Zoho ಸ್ಥಳಕ್ಕೆ ಜೋಡಿಸಲಾಗಿಲ್ಲ. ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "This product is not linked to Zoho yet. Ask head office.": "ಈ ಉತ್ಪನ್ನವನ್ನು ಇನ್ನೂ Zoho ಗೆ ಜೋಡಿಸಲಾಗಿಲ್ಲ. ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "Zoho has no stock record for this item at your godown. Ask head office.": "ನಿಮ್ಮ ಗೋದಾಮಿನಲ್ಲಿ ಈ ವಸ್ತುವಿಗೆ Zoho ದಲ್ಲಿ ದಾಸ್ತಾನು ದಾಖಲೆ ಇಲ್ಲ. ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "Zoho has the new count, but the website could not save it. The website catches up at the next Zoho sync (within 15 minutes).": "Zoho ದಲ್ಲಿ ಹೊಸ ಎಣಿಕೆ ಇದೆ, ಆದರೆ ವೆಬ್‌ಸೈಟ್ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮುಂದಿನ Zoho ಸಿಂಕ್‌ನಲ್ಲಿ (15 ನಿಮಿಷದೊಳಗೆ) ವೆಬ್‌ಸೈಟ್ ಸರಿಯಾಗುತ್ತದೆ.",
  "The count could not be saved. Try again.": "ಎಣಿಕೆ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
