  "Stock updates · {0}": "ದಾಸ್ತಾನು ನವೀಕರಣಗಳು · {0}",
  "Big changes (over 20%)": "ದೊಡ್ಡ ಬದಲಾವಣೆಗಳು (20% ಕ್ಕಿಂತ ಹೆಚ್ಚು)",
