  "Godowns counting": "ಎಣಿಕೆ ಮಾಡುತ್ತಿರುವ ಗೋದಾಮುಗಳು",
  "Stock updates by godown staff · {0}": "ಗೋದಾಮು ಸಿಬ್ಬಂದಿಯ ದಾಸ್ತಾನು ನವೀಕರಣಗಳು · {0}",
