  "Search by phone or order number to trace a complaint back to its batch.": "ದೂರನ್ನು ಅದರ ಬ್ಯಾಚ್‌ವರೆಗೆ ಪತ್ತೆಹಚ್ಚಲು ಫೋನ್ ಅಥವಾ ಆರ್ಡರ್ ಸಂಖ್ಯೆಯಿಂದ ಹುಡುಕಿ.",
  "One purchase = one batch with its own stock number. Orders from this godown take the oldest batch first.": "ಒಂದು ಖರೀದಿ = ತನ್ನದೇ ದಾಸ್ತಾನು ಸಂಖ್ಯೆಯ ಒಂದು ಬ್ಯಾಚ್. ಈ ಗೋದಾಮಿನ ಆರ್ಡರ್‌ಗಳು ಮೊದಲು ಹಳೆಯ ಬ್ಯಾಚ್ ತೆಗೆದುಕೊಳ್ಳುತ್ತವೆ.",
