  "Too many codes were sent to this number. Please wait 10 minutes and try again.": "ಈ ಸಂಖ್ಯೆಗೆ ಹಲವು ಕೋಡ್‌ಗಳನ್ನು ಕಳುಹಿಸಲಾಗಿದೆ. ದಯವಿಟ್ಟು 10 ನಿಮಿಷ ಕಾಯಿರಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
