  "Shift {0} – {1} · grace {2} min · radius {3} m · photo every {4}": "ಶಿಫ್ಟ್ {0} – {1} · ರಿಯಾಯಿತಿ {2} ನಿಮಿಷ · ವ್ಯಾಪ್ತಿ {3} ಮೀ · ಪ್ರತಿ {4} ಫೋಟೋ",
  "Godown Staff Login | Grain Bazar": "ಗೋದಾಮು ಸಿಬ್ಬಂದಿ ಲಾಗಿನ್ | Grain Bazar",
  "Mark your attendance on your godown's attendance device. Sign in with your mobile number and the password the Grain Bazar office gave you.": "ನಿಮ್ಮ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನದಲ್ಲಿ ಹಾಜರಾತಿ ದಾಖಲಿಸಿ. ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು Grain Bazar ಕಚೇರಿ ನೀಡಿದ ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ಲಾಗಿನ್ ಆಗಿ.",
  "Enter your password": "ನಿಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಿ",
  "Incorrect mobile number or password": "ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಅಥವಾ ಪಾಸ್‌ವರ್ಡ್ ತಪ್ಪಾಗಿದೆ",
  "Check both and try again. Forgot your password? Ask the Grain Bazar office to set a new one.": "ಎರಡನ್ನೂ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ. ಪಾಸ್‌ವರ್ಡ್ ಮರೆತಿರಾ? ಹೊಸದನ್ನು ಹೊಂದಿಸಲು Grain Bazar ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "Forgot your password? Ask the Grain Bazar office to set a new one.": "ಪಾಸ್‌ವರ್ಡ್ ಮರೆತಿರಾ? ಹೊಸದನ್ನು ಹೊಂದಿಸಲು Grain Bazar ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "This is not a godown staff login": "ಇದು ಗೋದಾಮು ಸಿಬ್ಬಂದಿ ಲಾಗಿನ್ ಅಲ್ಲ",
  "Setting up the godown's attendance device?": "ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನವನ್ನು ಹೊಂದಿಸುತ್ತಿದ್ದೀರಾ?",
  "Register this device": "ಈ ಸಾಧನವನ್ನು ನೋಂದಾಯಿಸಿ",
  "Register Attendance Device | Grain Bazar": "ಹಾಜರಾತಿ ಸಾಧನ ನೋಂದಣಿ | Grain Bazar",
  "Godown Attendance Device": "ಗೋದಾಮು ಹಾಜರಾತಿ ಸಾಧನ",
  "Staff mark attendance only on their godown's registered phone or tablet. Head office gives a one-time code in Admin > Attendance > Godown devices.": "ಸಿಬ್ಬಂದಿ ತಮ್ಮ ಗೋದಾಮಿನ ನೋಂದಾಯಿತ ಫೋನ್ ಅಥವಾ ಟ್ಯಾಬ್ಲೆಟ್‌ನಲ್ಲಿ ಮಾತ್ರ ಹಾಜರಾತಿ ದಾಖಲಿಸುತ್ತಾರೆ. ಮುಖ್ಯ ಕಚೇರಿ Admin > Attendance > Godown devices ನಲ್ಲಿ ಒಂದು ಬಾರಿಯ ಕೋಡ್ ನೀಡುತ್ತದೆ.",
  "Checking this device…": "ಈ ಸಾಧನವನ್ನು ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
  "This device is registered": "ಈ ಸಾಧನ ನೋಂದಾಯಿತವಾಗಿದೆ",
  "Go to staff sign-in": "ಸಿಬ್ಬಂದಿ ಲಾಗಿನ್‌ಗೆ ಹೋಗಿ",
  "Unregister this device": "ಈ ಸಾಧನದ ನೋಂದಣಿ ತೆಗೆದುಹಾಕಿ",
  "Do this once, on the godown's own attendance phone or tablet.": "ಇದನ್ನು ಒಮ್ಮೆ, ಗೋದಾಮಿನ ಸ್ವಂತ ಹಾಜರಾತಿ ಫೋನ್ ಅಥವಾ ಟ್ಯಾಬ್ಲೆಟ್‌ನಲ್ಲಿ ಮಾಡಿ.",
  "Device code from head office": "ಮುಖ್ಯ ಕಚೇರಿಯಿಂದ ಬಂದ ಸಾಧನ ಕೋಡ್",
  "Registering…": "ನೋಂದಾಯಿಸಲಾಗುತ್ತಿದೆ…",
  "Device registered": "ಸಾಧನ ನೋಂದಾಯಿಸಲಾಗಿದೆ",
  "Could not register this device": "ಈ ಸಾಧನವನ್ನು ನೋಂದಾಯಿಸಲಾಗಲಿಲ್ಲ",
  "Use your godown's attendance device": "ನಿಮ್ಮ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನ ಬಳಸಿ",
  "This phone is not registered for attendance. Mark attendance on your godown's registered phone or tablet.": "ಈ ಫೋನ್ ಹಾಜರಾತಿಗೆ ನೋಂದಾಯಿತವಾಗಿಲ್ಲ. ನಿಮ್ಮ ಗೋದಾಮಿನ ನೋಂದಾಯಿತ ಫೋನ್ ಅಥವಾ ಟ್ಯಾಬ್ಲೆಟ್‌ನಲ್ಲಿ ಹಾಜರಾತಿ ದಾಖಲಿಸಿ.",
  "Register this device (needs a code from head office)": "ಈ ಸಾಧನವನ್ನು ನೋಂದಾಯಿಸಿ (ಮುಖ್ಯ ಕಚೇರಿಯ ಕೋಡ್ ಬೇಕು)",
  "This device is registered for {0}. Attendance for {1} must be marked on {2}'s device.": "ಈ ಸಾಧನ {0} ಗೆ ನೋಂದಾಯಿತವಾಗಿದೆ. {1} ನ ಹಾಜರಾತಿಯನ್ನು {2} ನ ಸಾಧನದಲ್ಲಿ ದಾಖಲಿಸಬೇಕು.",
