  "Outside ({0} m)": "ಹೊರಗೆ ({0} ಮೀ)",
  "No presence photos.": "ಹಾಜರಿ ಫೋಟೋಗಳಿಲ್ಲ.",
  "Presence {0}": "ಹಾಜರಿ {0}",
  "Staff Attendance | Grain Bazar": "ಸಿಬ್ಬಂದಿ ಹಾಜರಾತಿ | Grain Bazar",
  "You are {0} m from the godown. Move inside the godown (within {1} m) to mark attendance.": "ನೀವು ಗೋದಾಮಿನಿಂದ {0} ಮೀ ದೂರದಲ್ಲಿದ್ದೀರಿ. ಹಾಜರಾತಿ ದಾಖಲಿಸಲು ಗೋದಾಮಿನ ಒಳಗೆ ({1} ಮೀ ಒಳಗೆ) ಬನ್ನಿ.",
  "GPS is not precise enough here. Switch on precise location (GPS), stand near the door or a window and try again.": "ಇಲ್ಲಿ GPS ಸಾಕಷ್ಟು ನಿಖರವಾಗಿಲ್ಲ. ನಿಖರ ಸ್ಥಳ (GPS) ಆನ್ ಮಾಡಿ, ಬಾಗಿಲು ಅಥವಾ ಕಿಟಕಿಯ ಬಳಿ ನಿಂತು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Use your godown's attendance device. This phone is not registered for attendance.": "ನಿಮ್ಮ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನ ಬಳಸಿ. ಈ ಫೋನ್ ಹಾಜರಾತಿಗೆ ನೋಂದಾಯಿತವಾಗಿಲ್ಲ.",
  "This device is not registered for attendance (or was removed). Ask head office for a device code.": "ಈ ಸಾಧನ ಹಾಜರಾತಿಗೆ ನೋಂದಾಯಿತವಾಗಿಲ್ಲ (ಅಥವಾ ತೆಗೆದುಹಾಕಲಾಗಿದೆ). ಸಾಧನ ಕೋಡ್‌ಗಾಗಿ ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "This device belongs to {0}. Use your own godown's attendance device.": "ಈ ಸಾಧನ {0} ಗೆ ಸೇರಿದೆ. ನಿಮ್ಮ ಸ್ವಂತ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನ ಬಳಸಿ.",
  "Enter the 8-character code": "8 ಅಕ್ಷರಗಳ ಕೋಡ್ ನಮೂದಿಸಿ",
  "This code is wrong, used or expired. Ask head office for a new code.": "ಈ ಕೋಡ್ ತಪ್ಪಾಗಿದೆ, ಬಳಸಲಾಗಿದೆ ಅಥವಾ ಅವಧಿ ಮುಗಿದಿದೆ. ಹೊಸ ಕೋಡ್‌ಗಾಗಿ ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "This code was just used. Ask head office for a new code.": "ಈ ಕೋಡ್ ಈಗಷ್ಟೇ ಬಳಸಲಾಗಿದೆ. ಹೊಸ ಕೋಡ್‌ಗಾಗಿ ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "The device could not be registered. Try again.": "ಸಾಧನವನ್ನು ನೋಂದಾಯಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "The selfie must be a JPEG photo": "ಸೆಲ್ಫಿ JPEG ಫೋಟೋ ಆಗಿರಬೇಕು",
  "Your godown was not found. Contact the office.": "ನಿಮ್ಮ ಗೋದಾಮು ಸಿಗಲಿಲ್ಲ. ಕಚೇರಿಯನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "Attendance could not be saved. Try again.": "ಹಾಜರಾತಿ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Presence photos are switched off for your godown": "ನಿಮ್ಮ ಗೋದಾಮಿಗೆ ಹಾಜರಿ ಫೋಟೋಗಳನ್ನು ಆಫ್ ಮಾಡಲಾಗಿದೆ",
  "The presence photo could not be saved. Try again.": "ಹಾಜರಿ ಫೋಟೋ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Could not load the selfies": "ಸೆಲ್ಫಿಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ",
