  "Reports & Excel": "ವರದಿಗಳು ಮತ್ತು Excel",
  "Godown devices": "ಗೋದಾಮು ಸಾಧನಗಳು",
  "Attendance is not fully set up in the database yet (migration 20261101090000_attendance_v2).": "ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಹಾಜರಾತಿ ಇನ್ನೂ ಪೂರ್ಣವಾಗಿ ಹೊಂದಿಸಿಲ್ಲ (migration 20261101090000_attendance_v2).",
  "Head office has not set this godown's location yet, so nobody can check in.": "ಮುಖ್ಯ ಕಚೇರಿ ಈ ಗೋದಾಮಿನ ಸ್ಥಳವನ್ನು ಇನ್ನೂ ಹೊಂದಿಸಿಲ್ಲ, ಆದ್ದರಿಂದ ಯಾರೂ ಚೆಕ್-ಇನ್ ಮಾಡಲಾಗದು.",
