  "Your decision: {0}": "ನಿಮ್ಮ ನಿರ್ಧಾರ: {0}",
  "Click a day to see the selfies and location. Excel for any period: Reports & Excel.": "ಸೆಲ್ಫಿ ಮತ್ತು ಸ್ಥಳ ನೋಡಲು ದಿನದ ಮೇಲೆ ಕ್ಲಿಕ್ ಮಾಡಿ. ಯಾವುದೇ ಅವಧಿಯ Excel: ವರದಿಗಳು ಮತ್ತು Excel.",
