  "Choose a valid period": "ಸರಿಯಾದ ಅವಧಿ ಆಯ್ಕೆಮಾಡಿ",
  "Choose at most one year": "ಗರಿಷ್ಠ ಒಂದು ವರ್ಷ ಆಯ್ಕೆಮಾಡಿ",
  "Could not load the report": "ವರದಿ ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ",
  "Head office adds and removes employees. They sign in at": "ಮುಖ್ಯ ಕಚೇರಿ ಸಿಬ್ಬಂದಿಯನ್ನು ಸೇರಿಸುತ್ತದೆ ಮತ್ತು ತೆಗೆದುಹಾಕುತ್ತದೆ. ಅವರು ಲಾಗಿನ್ ಆಗುವುದು",
  "on the godown's attendance device.": "ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನದಲ್ಲಿ.",
  "Staff records can't be edited once created. You can reset a password or deactivate someone who has left.": "ಸಿಬ್ಬಂದಿ ದಾಖಲೆಯನ್ನು ರಚಿಸಿದ ನಂತರ ಬದಲಿಸಲಾಗದು. ಪಾಸ್‌ವರ್ಡ್ ಮರುಹೊಂದಿಸಬಹುದು ಅಥವಾ ಕೆಲಸ ಬಿಟ್ಟವರನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬಹುದು.",
  "Employees ({0})": "ಸಿಬ್ಬಂದಿ ({0})",
  "Mobile": "ಮೊಬೈಲ್",
  "Set a password": "ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಿ",
  "Reset password": "ಪಾಸ್‌ವರ್ಡ್ ಮರುಹೊಂದಿಸಿ",
  "Save password": "ಪಾಸ್‌ವರ್ಡ್ ಉಳಿಸಿ",
  "Suggest": "ಸೂಚಿಸಿ",
  "{0} deactivated: they can no longer sign in": "{0} ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ: ಇನ್ನು ಲಾಗಿನ್ ಆಗಲಾಗದು",
  "{0} reactivated": "{0} ಮರು ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ",
  "Password set for {0}": "{0} ಗೆ ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಲಾಗಿದೆ",
  "Password for {0}": "{0} ಗಾಗಿ ಪಾಸ್‌ವರ್ಡ್",
  "Copied. Share it with them; they sign in with their mobile number and this password.": "ನಕಲಿಸಲಾಗಿದೆ. ಅವರಿಗೆ ಹಂಚಿಕೊಳ್ಳಿ; ಅವರು ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ಈ ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ಲಾಗಿನ್ ಆಗುತ್ತಾರೆ.",
  "Mobile {0}. They sign in at {1} with this mobile number and the new password.": "ಮೊಬೈಲ್ {0}. ಅವರು {1} ನಲ್ಲಿ ಈ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ಹೊಸ ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ಲಾಗಿನ್ ಆಗುತ್ತಾರೆ.",
  "{0} added to {1}": "{0} ಅನ್ನು {1} ಗೆ ಸೇರಿಸಲಾಗಿದೆ",
  "Login details copied: mobile {0} and the password. Share them with the employee.": "ಲಾಗಿನ್ ವಿವರ ನಕಲಿಸಲಾಗಿದೆ: ಮೊಬೈಲ್ {0} ಮತ್ತು ಪಾಸ್‌ವರ್ಡ್. ಸಿಬ್ಬಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಿ.",
  "Check the details: name, mobile and godown can't be changed after the employee is added.": "ವಿವರ ಪರಿಶೀಲಿಸಿ: ಸಿಬ್ಬಂದಿ ಸೇರಿಸಿದ ನಂತರ ಹೆಸರು, ಮೊಬೈಲ್ ಮತ್ತು ಗೋದಾಮು ಬದಲಿಸಲಾಗದು.",
  "Employees sign in at {0} on the godown's attendance device with their mobile number and password.": "ಸಿಬ್ಬಂದಿ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಸಾಧನದಲ್ಲಿ {0} ನಲ್ಲಿ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಮತ್ತು ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ಲಾಗಿನ್ ಆಗುತ್ತಾರೆ.",
  "Copy link": "ಲಿಂಕ್ ನಕಲಿಸಿ",
  "Link copied": "ಲಿಂಕ್ ನಕಲಿಸಲಾಗಿದೆ",
  "Location taken (±{0} m)": "ಸ್ಥಳ ಪಡೆಯಲಾಗಿದೆ (±{0} ಮೀ)",
  "Save to use it.": "ಬಳಸಲು ಉಳಿಸಿ.",
  "Radius (m): staff can check in and out only within it": "ವ್ಯಾಪ್ತಿ (ಮೀ): ಸಿಬ್ಬಂದಿ ಇದರೊಳಗೆ ಮಾತ್ರ ಚೆಕ್-ಇನ್/ಔಟ್ ಮಾಡಬಹುದು",
  "Presence photo (live geotagged selfie while checked in)": "ಹಾಜರಿ ಫೋಟೋ (ಚೆಕ್-ಇನ್ ಆಗಿರುವಾಗ ಸ್ಥಳ ಸಹಿತ ನೇರ ಸೆಲ್ಫಿ)",
  "Every {0}": "ಪ್ರತಿ {0}",
  "Radius must be 25 to 2000 metres": "ವ್ಯಾಪ್ತಿ 25 ರಿಂದ 2000 ಮೀಟರ್ ಇರಬೇಕು",
  "Grace must be 0 to 240 minutes": "ರಿಯಾಯಿತಿ 0 ರಿಂದ 240 ನಿಮಿಷ ಇರಬೇಕು",
  "Enter the shift start and end times": "ಶಿಫ್ಟ್ ಆರಂಭ ಮತ್ತು ಮುಕ್ತಾಯ ಸಮಯ ನಮೂದಿಸಿ",
  "The shift must end after it starts": "ಶಿಫ್ಟ್ ಆರಂಭವಾದ ನಂತರವೇ ಮುಗಿಯಬೇಕು",
  "{0} · attendance devices": "{0} · ಹಾಜರಾತಿ ಸಾಧನಗಳು",
  "Staff mark attendance only on this godown's registered phone or tablet. To register one, make a code here, then on that device open": "ಸಿಬ್ಬಂದಿ ಈ ಗೋದಾಮಿನ ನೋಂದಾಯಿತ ಫೋನ್ ಅಥವಾ ಟ್ಯಾಬ್ಲೆಟ್‌ನಲ್ಲಿ ಮಾತ್ರ ಹಾಜರಾತಿ ದಾಖಲಿಸುತ್ತಾರೆ. ನೋಂದಾಯಿಸಲು ಇಲ್ಲಿ ಕೋಡ್ ಮಾಡಿ, ನಂತರ ಆ ಸಾಧನದಲ್ಲಿ ತೆರೆಯಿರಿ",
  "and enter the code (valid 15 minutes, once).": "ಮತ್ತು ಕೋಡ್ ನಮೂದಿಸಿ (15 ನಿಮಿಷ, ಒಂದು ಬಾರಿ ಮಾನ್ಯ).",
  "Device name (optional)": "ಸಾಧನದ ಹೆಸರು (ಐಚ್ಛಿಕ)",
  "Godown tablet": "ಗೋದಾಮು ಟ್ಯಾಬ್ಲೆಟ್",
  "Make device code": "ಸಾಧನ ಕೋಡ್ ಮಾಡಿ",
  "Making code…": "ಕೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
  "Device code": "ಸಾಧನ ಕೋಡ್",
  "Valid until {0}, once.": "{0} ವರೆಗೆ, ಒಂದು ಬಾರಿ ಮಾನ್ಯ.",
  "Registered devices ({0})": "ನೋಂದಾಯಿತ ಸಾಧನಗಳು ({0})",
  "No device registered yet: nobody at this godown can mark attendance.": "ಇನ್ನೂ ಯಾವುದೇ ಸಾಧನ ನೋಂದಾಯಿಸಿಲ್ಲ: ಈ ಗೋದಾಮಿನಲ್ಲಿ ಯಾರೂ ಹಾಜರಾತಿ ದಾಖಲಿಸಲಾಗದು.",
  "{0} removed: it can no longer mark attendance": "{0} ತೆಗೆದುಹಾಕಲಾಗಿದೆ: ಇನ್ನು ಹಾಜರಾತಿ ದಾಖಲಿಸಲಾಗದು",
  "Could not make a code": "ಕೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ",
