  "(time from older records, approximate)": "(ಹಳೆಯ ದಾಖಲೆಗಳಿಂದ ಸಮಯ, ಅಂದಾಜು)",
  "Added by {0}": "ಸೇರಿಸಿದವರು {0}",
  "Ended by {0}": "ಕೊನೆಗೊಳಿಸಿದವರು {0}",
  "Added by {0} · Ended by {1}": "ಸೇರಿಸಿದವರು {0} · ಕೊನೆಗೊಳಿಸಿದವರು {1}",
  "Sales (no commission)": "ಮಾರಾಟ (ಕಮಿಷನ್ ಇಲ್ಲ)",
  "Sales excl. GST": "ಮಾರಾಟ (GST ಹೊರತು)",
  "Partner history downloaded": "ಪಾಲುದಾರರ ಇತಿಹಾಸ ಡೌನ್‌ಲೋಡ್ ಆಗಿದೆ",
  "A request can cover at most {0} days": "ಒಂದು ವಿನಂತಿ ಗರಿಷ್ಠ {0} ದಿನಗಳು",
  "Leave more than {0} days ago can't be requested": "{0} ದಿನಗಳಿಗಿಂತ ಹಿಂದಿನ ರಜೆ ಕೇಳಲು ಆಗದು",
  "Leave for past days can't be requested": "ಕಳೆದ ದಿನಗಳ ರಜೆ ಕೇಳಲು ಆಗದು",
  "Request leave at most {0} days ahead": "ಗರಿಷ್ಠ {0} ದಿನ ಮುಂಚಿತವಾಗಿ ರಜೆ ಕೇಳಿ",
  "This type of leave is not available at your godown": "ಈ ಬಗೆಯ ರಜೆ ನಿಮ್ಮ ಗೋದಾಮಿನಲ್ಲಿ ಲಭ್ಯವಿಲ್ಲ",
  "Godown rules": "ಗೋದಾಮು ನಿಯಮಗಳು",
  "Head office has not set this godown's location yet. Ask head office to set it in Godown rules.": "ಮುಖ್ಯ ಕಚೇರಿ ಈ ಗೋದಾಮಿನ ಸ್ಥಳವನ್ನು ಇನ್ನೂ ಹೊಂದಿಸಿಲ್ಲ. ಗೋದಾಮು ನಿಯಮಗಳಲ್ಲಿ ಹೊಂದಿಸಲು ಮುಖ್ಯ ಕಚೇರಿಯನ್ನು ಕೇಳಿ.",
  "Set this godown's location in Godown rules. Until then nobody at this godown can check in.": "ಗೋದಾಮು ನಿಯಮಗಳಲ್ಲಿ ಈ ಗೋದಾಮಿನ ಸ್ಥಳ ಹೊಂದಿಸಿ. ಅಲ್ಲಿಯವರೆಗೆ ಈ ಗೋದಾಮಿನಲ್ಲಿ ಯಾರೂ ಚೆಕ್-ಇನ್ ಮಾಡಲಾಗದು.",
  "Check-ins need no approval. Who approves leave follows each godown's rules.": "ಚೆಕ್-ಇನ್‌ಗೆ ಅನುಮೋದನೆ ಬೇಕಿಲ್ಲ. ರಜೆಯನ್ನು ಯಾರು ಅನುಮೋದಿಸಬೇಕು ಎಂಬುದು ಪ್ರತಿ ಗೋದಾಮಿನ ನಿಯಮದಂತೆ.",
  "P present · L present but late · HD half day · LV approved leave · WO weekly off · H holiday · A absent": "P ಹಾಜರು · L ಹಾಜರು ಆದರೆ ತಡ · HD ಅರ್ಧ ದಿನ · LV ಅನುಮೋದಿತ ರಜೆ · WO ವಾರದ ರಜೆ · H ರಜಾದಿನ · A ಗೈರು",
  "Half day": "ಅರ್ಧ ದಿನ",
  "Half days": "ಅರ್ಧ ದಿನಗಳು",
  "Holiday": "ರಜಾದಿನ",
  "Holidays": "ರಜಾದಿನಗಳು",
  "Weekly off": "ವಾರದ ರಜೆ",
  "The left-early allowance must be 0 to 240 minutes": "ಮುಂಚೆ ಹೊರಡುವ ರಿಯಾಯಿತಿ 0 ರಿಂದ 240 ನಿಮಿಷ ಇರಬೇಕು",
  "Hours worked must be 0 to 24": "ಕೆಲಸದ ಗಂಟೆಗಳು 0 ರಿಂದ 24 ಇರಬೇಕು",
  "The absent limit must be below the half day limit": "ಗೈರು ಮಿತಿ ಅರ್ಧ ದಿನದ ಮಿತಿಗಿಂತ ಕಡಿಮೆ ಇರಬೇಕು",
  "The GPS limit must be 10 to 2000 metres": "ಜಿಪಿಎಸ್ ಮಿತಿ 10 ರಿಂದ 2000 ಮೀಟರ್ ಇರಬೇಕು",
  "Presence photos must be 30 minutes to 8 hours apart": "ಹಾಜರಿ ಫೋಟೋಗಳ ನಡುವೆ 30 ನಿಮಿಷದಿಂದ 8 ಗಂಟೆ ಅಂತರ ಇರಬೇಕು",
  "The presence photo window must be 0 to 120 minutes before and 0 to 240 after": "ಹಾಜರಿ ಫೋಟೋ ಸಮಯ ಮಿತಿ 0 ರಿಂದ 120 ನಿಮಿಷ ಮೊದಲು ಮತ್ತು 0 ರಿಂದ 240 ನಿಮಿಷ ನಂತರ ಇರಬೇಕು",
