  "New rules can start today or later. Past days keep the rules they had.": "ಹೊಸ ನಿಯಮಗಳು ಇಂದು ಅಥವಾ ನಂತರ ಆರಂಭವಾಗಬಹುದು. ಕಳೆದ ದಿನಗಳಿಗೆ ಅವುಗಳ ಹಳೆಯ ನಿಯಮಗಳೇ ಉಳಿಯುತ್ತವೆ.",
