  "The Excel file has these sheets: Dashboard, Staff (details and totals), Daily attendance (check-in, check-out, late, early, worked), Presence photos, Register per godown, Leave history and Rules (each godown's rules and holidays over the period).": "Excel ಫೈಲ್‌ನಲ್ಲಿ ಈ ಶೀಟ್‌ಗಳಿವೆ: ಡ್ಯಾಶ್‌ಬೋರ್ಡ್, ಸಿಬ್ಬಂದಿ (ವಿವರ ಮತ್ತು ಒಟ್ಟು), ದೈನಂದಿನ ಹಾಜರಾತಿ (ಚೆಕ್-ಇನ್, ಚೆಕ್-ಔಟ್, ತಡ, ಮುಂಚೆ, ಕೆಲಸದ ಸಮಯ), ಹಾಜರಿ ಫೋಟೋಗಳು, ಪ್ರತಿ ಗೋದಾಮಿನ ಹಾಜರಾತಿ ಪುಸ್ತಕ, ರಜೆ ಇತಿಹಾಸ ಮತ್ತು ನಿಯಮಗಳು (ಪ್ರತಿ ಗೋದಾಮಿನ ನಿಯಮಗಳು ಮತ್ತು ರಜಾದಿನಗಳು ಸೇರಿ).",
  "Late = check-in after {0} + {1} min, counted from {2}.": "ತಡ = {0} + {1} ನಿಮಿಷದ ನಂತರ ಚೆಕ್-ಇನ್, {2} ರಿಂದ ಎಣಿಕೆ.",
  "the end of grace": "ರಿಯಾಯಿತಿ ಮುಗಿದ ಸಮಯ",
  "Left early = check-out before {0}.": "ಮುಂಚೆ ಹೊರಟದ್ದು = {0} ಕ್ಕಿಂತ ಮೊದಲು ಚೆಕ್-ಔಟ್.",
  "Left early = check-out more than {0} min before {1}.": "ಮುಂಚೆ ಹೊರಟದ್ದು = {1} ಕ್ಕಿಂತ {0} ನಿಮಿಷಕ್ಕೂ ಹೆಚ್ಚು ಮೊದಲು ಚೆಕ್-ಔಟ್.",
  "A change is scheduled from {0}. New rules can start from that date. To change rules sooner, first cancel it in Rule history.": "{0} ರಿಂದ ಒಂದು ಬದಲಾವಣೆ ನಿಗದಿಯಾಗಿದೆ. ಹೊಸ ನಿಯಮಗಳು ಆ ದಿನದಿಂದ ಆರಂಭವಾಗಬಹುದು. ಅದಕ್ಕಿಂತ ಮೊದಲು ಬದಲಿಸಲು, ಮೊದಲು ನಿಯಮಗಳ ಇತಿಹಾಸದಲ್ಲಿ ಅದನ್ನು ರದ್ದುಮಾಡಿ.",
  "A change is already scheduled from {0}. Cancel it first, or start these rules on or after that date.": "{0} ರಿಂದ ಒಂದು ಬದಲಾವಣೆ ಈಗಾಗಲೇ ನಿಗದಿಯಾಗಿದೆ. ಮೊದಲು ಅದನ್ನು ರದ್ದುಮಾಡಿ, ಅಥವಾ ಈ ನಿಯಮಗಳನ್ನು ಆ ದಿನ ಅಥವಾ ನಂತರದಿಂದ ಆರಂಭಿಸಿ.",
  "Cancel the later scheduled change first": "ಮೊದಲು ನಂತರದ ನಿಗದಿತ ಬದಲಾವಣೆಯನ್ನು ರದ್ದುಮಾಡಿ",
  // Batches from Zoho bills (5 Nov 2026)
  "Receive purchase from a Zoho bill": "Zoho ಬಿಲ್‌ನಿಂದ ಖರೀದಿ ಸ್ವೀಕರಿಸಿ",
  "Pick the bill: each line becomes one batch with its own stock number. The bill already added the stock in Zoho, so stock does not change here.": "ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ: ಪ್ರತಿ ಸಾಲು ತನ್ನದೇ ದಾಸ್ತಾನು ಸಂಖ್ಯೆಯ ಒಂದು ಬ್ಯಾಚ್ ಆಗುತ್ತದೆ. ಬಿಲ್ ಈಗಾಗಲೇ Zoho ದಲ್ಲಿ ದಾಸ್ತಾನು ಸೇರಿಸಿದೆ, ಆದ್ದರಿಂದ ಇಲ್ಲಿ ದಾಸ್ತಾನು ಬದಲಾಗುವುದಿಲ್ಲ.",
  "Refresh bills": "ಬಿಲ್‌ಗಳನ್ನು ರಿಫ್ರೆಶ್ ಮಾಡಿ",
  "Recent bills": "ಇತ್ತೀಚಿನ ಬಿಲ್‌ಗಳು",
  "No recent bills for this godown in Zoho.": "Zoho ದಲ್ಲಿ ಈ ಗೋದಾಮಿಗೆ ಇತ್ತೀಚಿನ ಬಿಲ್‌ಗಳಿಲ್ಲ.",
  "No batches yet": "ಇನ್ನೂ ಬ್ಯಾಚ್‌ಗಳಿಲ್ಲ",
  "{0} line{1} already batched": "{0} ಸಾಲು{1} ಈಗಾಗಲೇ ಬ್ಯಾಚ್ ಆಗಿವೆ",
  "Bill date {0}": "ಬಿಲ್ ದಿನಾಂಕ {0}",
  "Sub total": "ಉಪ ಮೊತ್ತ",
  "Discount on whole bill": "ಸಂಪೂರ್ಣ ಬಿಲ್ ಮೇಲಿನ ರಿಯಾಯಿತಿ",
  "Round-off": "ರೌಂಡ್-ಆಫ್",
  "Other bill": "ಬೇರೆ ಬಿಲ್",
  "Cost these batches use": "ಈ ಬ್ಯಾಚ್‌ಗಳು ಬಳಸುವ ವೆಚ್ಚ",
  "Cost without GST": "GST ಇಲ್ಲದ ವೆಚ್ಚ",
  "Cost with GST": "GST ಸಹಿತ ವೆಚ್ಚ",
  "Cost typed in": "ಟೈಪ್ ಮಾಡಿದ ವೆಚ್ಚ",
  "Taxable amount per unit. Use when GST paid is claimed back.": "ಪ್ರತಿ ಘಟಕದ ತೆರಿಗೆಗೆ ಒಳಪಡುವ ಮೊತ್ತ. ಪಾವತಿಸಿದ GST ಮರಳಿ ಪಡೆಯುವಾಗ ಬಳಸಿ.",
  "Taxable amount plus GST per unit. Use when GST paid is a cost.": "ಪ್ರತಿ ಘಟಕದ ತೆರಿಗೆಗೆ ಒಳಪಡುವ ಮೊತ್ತ ಮತ್ತು GST. ಪಾವತಿಸಿದ GST ವೆಚ್ಚವಾದಾಗ ಬಳಸಿ.",
  "Both costs are saved on each batch. Profit uses the one chosen here and says which.": "ಎರಡೂ ವೆಚ್ಚಗಳು ಪ್ರತಿ ಬ್ಯಾಚ್‌ನಲ್ಲಿ ಉಳಿಯುತ್ತವೆ. ಲಾಭ ಇಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡಿದ ವೆಚ್ಚವನ್ನು ಬಳಸುತ್ತದೆ ಮತ್ತು ಯಾವುದು ಎಂದು ತೋರಿಸುತ್ತದೆ.",
  "Website: {0}": "ವೆಬ್‌ಸೈಟ್: {0}",
