  "The quantity is too high. It should be in quintals.": "ಪ್ರಮಾಣ ತುಂಬಾ ಹೆಚ್ಚಾಗಿದೆ. ಅದು ಕ್ವಿಂಟಾಲ್‌ನಲ್ಲಿ ಇರಬೇಕು.",
