  "Enter the weight of one bag: 1 to 100 kg, one decimal at most (like 26 or 26.5)": "ಒಂದು ಚೀಲದ ತೂಕ ನಮೂದಿಸಿ: 1 ರಿಂದ 100 kg, ಹೆಚ್ಚೆಂದರೆ ಒಂದು ದಶಮಾಂಶ (26 ಅಥವಾ 26.5 ರಂತೆ)",
  "That is too many bags.": "ಅದು ತುಂಬಾ ಹೆಚ್ಚು ಚೀಲಗಳು.",
  "Bags can't be saved yet": "ಚೀಲಗಳನ್ನು ಇನ್ನೂ ಉಳಿಸಲು ಆಗುವುದಿಲ್ಲ",
  "The database update for bags is not applied. Choose Quintal for now.": "ಚೀಲಗಳ ಡೇಟಾಬೇಸ್ ಅಪ್‌ಡೇಟ್ ಇನ್ನೂ ಅನ್ವಯಿಸಿಲ್ಲ. ಸದ್ಯಕ್ಕೆ ಕ್ವಿಂಟಾಲ್ ಆಯ್ಕೆಮಾಡಿ.",
  "Enter both the number of bags and the weight of one bag": "ಚೀಲಗಳ ಸಂಖ್ಯೆ ಮತ್ತು ಒಂದು ಚೀಲದ ತೂಕ ಎರಡನ್ನೂ ನಮೂದಿಸಿ",
  "One bag must weigh from 1 to 100 kg": "ಒಂದು ಚೀಲದ ತೂಕ 1 ರಿಂದ 100 kg ಇರಬೇಕು",
  "Enter the bag weight with one decimal at most, like 26 or 26.5": "ಚೀಲದ ತೂಕವನ್ನು ಹೆಚ್ಚೆಂದರೆ ಒಂದು ದಶಮಾಂಶದೊಂದಿಗೆ ನಮೂದಿಸಿ, 26 ಅಥವಾ 26.5 ರಂತೆ",
  "The page showed {0} quintal, but {1} bags of {2} kg is {3} quintal. Reload the page and try again.": "ಪುಟ {0} ಕ್ವಿಂಟಾಲ್ ತೋರಿಸಿತು, ಆದರೆ {2} kg ನ {1} ಚೀಲಗಳು {3} ಕ್ವಿಂಟಾಲ್. ಪುಟವನ್ನು ಮರುಲೋಡ್ ಮಾಡಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
