  // Back from the UPI app (7 Nov 2026).
  "Come back here and enter the 12-digit UPI Ref No. (UTR) from the payment receipt. Our team confirms it with our bank and your order is placed.": "ಇಲ್ಲಿಗೆ ಹಿಂತಿರುಗಿ, ಪಾವತಿ ರಸೀದಿಯಲ್ಲಿರುವ 12 ಅಂಕಿಯ UPI Ref No. (UTR) ನಮೂದಿಸಿ. ನಮ್ಮ ತಂಡ ಅದನ್ನು ನಮ್ಮ ಬ್ಯಾಂಕ್‌ನೊಂದಿಗೆ ಖಚಿತಪಡಿಸುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಆರ್ಡರ್ ಆಗುತ್ತದೆ.",
  "Payment done? Enter its UPI Ref No. now": "ಪಾವತಿ ಆಯಿತೇ? ಈಗಲೇ ಅದರ UPI Ref No. ನಮೂದಿಸಿ",
  "It is the 12-digit number on the receipt in your UPI app (UPI Ref No., UPI transaction ID or UTR). Your order is kept for you while you enter it.": "ಇದು ನಿಮ್ಮ UPI ಆ್ಯಪ್‌ನ ರಸೀದಿಯಲ್ಲಿರುವ 12 ಅಂಕಿಯ ಸಂಖ್ಯೆ (UPI Ref No., UPI transaction ID ಅಥವಾ UTR). ನೀವು ಅದನ್ನು ನಮೂದಿಸುವವರೆಗೆ ನಿಮ್ಮ ಆರ್ಡರ್ ಕಾಯ್ದಿರಿಸಲಾಗುತ್ತದೆ.",
  "Paid? Enter the 12-digit UPI Ref No. (UTR) from your UPI app": "ಪಾವತಿಸಿದಿರಾ? ನಿಮ್ಮ UPI ಆ್ಯಪ್‌ನಿಂದ 12 ಅಂಕಿಯ UPI Ref No. (UTR) ನಮೂದಿಸಿ",
  // Each godown's Zoho deposit account (Admin > Payments & Matching, Branches).
  "Zoho bank account for each godown's payments": "ಪ್ರತಿ ಗೋದಾಮಿನ ಪಾವತಿಗಳಿಗೆ Zoho ಬ್ಯಾಂಕ್ ಖಾತೆ",
  "Load accounts from Zoho": "Zoho ನಿಂದ ಖಾತೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ",
  "Reload accounts from Zoho": "Zoho ನಿಂದ ಖಾತೆಗಳನ್ನು ಮರುಲೋಡ್ ಮಾಡಿ",
  "Payments confirmed on the website are recorded in Zoho Books against the order's invoice. Choose the Zoho bank account each godown's payments are deposited to. With none chosen, Zoho puts them in Undeposited Funds.": "ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿ ದೃಢಪಟ್ಟ ಪಾವತಿಗಳನ್ನು ಆರ್ಡರ್‌ನ ಇನ್‌ವಾಯ್ಸ್ ವಿರುದ್ಧ Zoho Books ನಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಪ್ರತಿ ಗೋದಾಮಿನ ಪಾವತಿಗಳು ಜಮೆಯಾಗುವ Zoho ಬ್ಯಾಂಕ್ ಖಾತೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಯಾವುದನ್ನೂ ಆಯ್ಕೆ ಮಾಡದಿದ್ದರೆ, Zoho ಅವುಗಳನ್ನು Undeposited Funds ನಲ್ಲಿ ಇಡುತ್ತದೆ.",
  "Only payments recorded from now on use the account. Payments already in Zoho stay where they are; change those in Zoho Books.": "ಇನ್ನು ಮುಂದೆ ದಾಖಲಾಗುವ ಪಾವತಿಗಳು ಮಾತ್ರ ಈ ಖಾತೆಯನ್ನು ಬಳಸುತ್ತವೆ. ಈಗಾಗಲೇ Zoho ನಲ್ಲಿರುವ ಪಾವತಿಗಳು ಇದ್ದಲ್ಲೇ ಇರುತ್ತವೆ; ಅವುಗಳನ್ನು Zoho Books ನಲ್ಲಿ ಬದಲಾಯಿಸಿ.",
  "No godowns yet.": "ಇನ್ನೂ ಯಾವುದೇ ಗೋದಾಮುಗಳಿಲ್ಲ.",
  "Undeposited Funds (Zoho's default)": "Undeposited Funds (Zoho ನ ಡೀಫಾಲ್ಟ್)",
  "This account is no longer an active bank account in Zoho Books. Payments for this godown will not be recorded until you choose another.": "ಈ ಖಾತೆ ಇನ್ನು Zoho Books ನಲ್ಲಿ ಸಕ್ರಿಯ ಬ್ಯಾಂಕ್ ಖಾತೆಯಾಗಿಲ್ಲ. ನೀವು ಬೇರೊಂದನ್ನು ಆಯ್ಕೆಮಾಡುವವರೆಗೆ ಈ ಗೋದಾಮಿನ ಪಾವತಿಗಳು ದಾಖಲಾಗುವುದಿಲ್ಲ.",
  "Deposit payments to": "ಪಾವತಿಗಳನ್ನು ಜಮೆ ಮಾಡುವ ಖಾತೆ",
  "{0} (cash)": "{0} (ನಗದು)",
  "{0} (no longer active in Zoho)": "{0} (Zoho ನಲ್ಲಿ ಇನ್ನು ಸಕ್ರಿಯವಾಗಿಲ್ಲ)",
  "Loading accounts from Zoho…": "Zoho ನಿಂದ ಖಾತೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗುತ್ತಿದೆ…",
  "Load the accounts from Zoho first.": "ಮೊದಲು Zoho ನಿಂದ ಖಾತೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ.",
  "Could not read the saved accounts. Click \"Load accounts from Zoho\" or reload the page.": "ಉಳಿಸಿದ ಖಾತೆಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. \"Zoho ನಿಂದ ಖಾತೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ\" ಕ್ಲಿಕ್ ಮಾಡಿ ಅಥವಾ ಪುಟವನ್ನು ಮರುಲೋಡ್ ಮಾಡಿ.",
  "Could not load the bank accounts from Zoho": "Zoho ನಿಂದ ಬ್ಯಾಂಕ್ ಖಾತೆಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Could not save the deposit account": "ಜಮೆ ಖಾತೆಯನ್ನು ಉಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ",
  "Saved for {0}": "{0} ಗಾಗಿ ಉಳಿಸಲಾಗಿದೆ",
  "New payments go to {0}": "ಹೊಸ ಪಾವತಿಗಳು {0} ಗೆ ಹೋಗುತ್ತವೆ",
  "New payments go to Undeposited Funds": "ಹೊಸ ಪಾವತಿಗಳು Undeposited Funds ಗೆ ಹೋಗುತ್ತವೆ",
  "Payments deposited to:": "ಪಾವತಿಗಳು ಜಮೆಯಾಗುವ ಖಾತೆ:",
  "That account is not an active bank or cash account in Zoho Books. Reload the list and choose again.": "ಆ ಖಾತೆ Zoho Books ನಲ್ಲಿ ಸಕ್ರಿಯ ಬ್ಯಾಂಕ್ ಅಥವಾ ನಗದು ಖಾತೆಯಲ್ಲ. ಪಟ್ಟಿಯನ್ನು ಮರುಲೋಡ್ ಮಾಡಿ ಮತ್ತೆ ಆಯ್ಕೆಮಾಡಿ.",
