  "This month is still running. The figures change as orders are delivered and paid.": "ಈ ತಿಂಗಳು ಇನ್ನೂ ನಡೆಯುತ್ತಿದೆ. ಆರ್ಡರ್‌ಗಳು ಡೆಲಿವರಿ ಆಗಿ ಪಾವತಿಯಾದಂತೆ ಅಂಕಿಗಳು ಬದಲಾಗುತ್ತವೆ.",
  "The office will check this month and close it. After that the deductions are locked.": "ಕಚೇರಿಯು ಈ ತಿಂಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮುಚ್ಚುತ್ತದೆ. ಅದರ ನಂತರ ಕಡಿತಗಳನ್ನು ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ.",
