  "No favourites yet. Tap the star next to a page or button to keep it here.": "ಇನ್ನೂ ಮೆಚ್ಚಿನವು ಇಲ್ಲ. ಪುಟ ಅಥವಾ ಬಟನ್ ಪಕ್ಕದ ನಕ್ಷತ್ರವನ್ನು ಒತ್ತಿ, ಅದು ಇಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.",
  "Type a page or button name, for example: add employee. Ctrl+K or / opens this search from anywhere.": "ಪುಟ ಅಥವಾ ಬಟನ್ ಹೆಸರನ್ನು ಟೈಪ್ ಮಾಡಿ, ಉದಾಹರಣೆಗೆ: add employee. Ctrl+K ಅಥವಾ / ಎಲ್ಲಿಂದಲಾದರೂ ಈ ಹುಡುಕಾಟ ತೆರೆಯುತ್ತದೆ.",
