  "Search order no., customer, PIN code or product": "ಆರ್ಡರ್ ಸಂಖ್ಯೆ, ಗ್ರಾಹಕ, ಪಿನ್ ಕೋಡ್ ಅಥವಾ ಉತ್ಪನ್ನವನ್ನು ಹುಡುಕಿ",
