  "No delivery notes match. Clear the search or pick another filter.": "ಯಾವುದೇ ಡೆಲಿವರಿ ನೋಟ್ ಹೊಂದುತ್ತಿಲ್ಲ. ಹುಡುಕಾಟ ತೆರವುಗೊಳಿಸಿ ಅಥವಾ ಬೇರೆ ಫಿಲ್ಟರ್ ಆರಿಸಿ.",
