  "Your number in our accounts. It is printed on your invoices.": "ನಮ್ಮ ಲೆಕ್ಕಪತ್ರದಲ್ಲಿ ನಿಮ್ಮ ಸಂಖ್ಯೆ. ಇದು ನಿಮ್ಮ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ಮುದ್ರಿತವಾಗುತ್ತದೆ.",
  "Your number in our accounts.": "ನಮ್ಮ ಲೆಕ್ಕಪತ್ರದಲ್ಲಿ ನಿಮ್ಮ ಸಂಖ್ಯೆ.",
  "Customer and vendor numbers": "ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆಗಳು",
  "Zoho Books gives each customer and vendor a number (Customer No. / Vendor No.). The website shows it on the customer and vendor pages, on orders, on invoices and on delivery notes and slips.": "Zoho Books ಪ್ರತಿ ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರರಿಗೆ ಒಂದು ಸಂಖ್ಯೆ ನೀಡುತ್ತದೆ (ಗ್ರಾಹಕ ಸಂಖ್ಯೆ / ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆ). ವೆಬ್‌ಸೈಟ್ ಅದನ್ನು ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರರ ಪುಟಗಳಲ್ಲಿ, ಆರ್ಡರ್‌ಗಳಲ್ಲಿ, ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ಮತ್ತು ಡೆಲಿವರಿ ನೋಟ್ ಹಾಗೂ ಸ್ಲಿಪ್‌ಗಳಲ್ಲಿ ತೋರಿಸುತ್ತದೆ.",
  "Each press reads up to {0} linked contacts from Zoho. Nothing is changed in Zoho.": "ಪ್ರತಿ ಬಾರಿ ಒತ್ತಿದಾಗ Zoho ದಿಂದ ಜೋಡಿಸಲಾದ {0} ಸಂಪರ್ಕಗಳವರೆಗೆ ಓದಲಾಗುತ್ತದೆ. Zoho ದಲ್ಲಿ ಏನನ್ನೂ ಬದಲಾಯಿಸುವುದಿಲ್ಲ.",
  "Fetching numbers…": "ಸಂಖ್ಯೆಗಳನ್ನು ತರಲಾಗುತ್ತಿದೆ…",
  "Fetch customer and vendor numbers from Zoho": "Zoho ದಿಂದ ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆಗಳನ್ನು ತನ್ನಿ",
  "Customer and vendor numbers fetched": "ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆಗಳನ್ನು ತರಲಾಗಿದೆ",
  "Zoho contact IDs not read:": "ಓದಲಾಗದ Zoho ಸಂಪರ್ಕ ID ಗಳು:",
  "Could not read the Zoho contact links": "Zoho ಸಂಪರ್ಕ ಜೋಡಣೆಗಳನ್ನು ಓದಲಾಗಲಿಲ್ಲ",
  "The database does not have the customer and vendor number update yet. Nothing was asked of Zoho. Ask your developer to apply it.": "ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಇನ್ನೂ ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆಯ ಅಪ್‌ಡೇಟ್ ಇಲ್ಲ. Zoho ಗೆ ಏನನ್ನೂ ಕೇಳಲಿಲ್ಲ. ಅದನ್ನು ಅನ್ವಯಿಸಲು ನಿಮ್ಮ ಡೆವಲಪರ್‌ಗೆ ಹೇಳಿ.",
  "Zoho's daily API limit was reached, so nothing was asked. Try again after the pause ends.": "Zoho ದ ದೈನಂದಿನ API ಮಿತಿ ತಲುಪಿದೆ, ಆದ್ದರಿಂದ ಏನನ್ನೂ ಕೇಳಲಿಲ್ಲ. ವಿರಾಮ ಮುಗಿದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Zoho's daily API limit was reached, so the rest were not asked. Try again after the pause ends.": "Zoho ದ ದೈನಂದಿನ API ಮಿತಿ ತಲುಪಿದೆ, ಆದ್ದರಿಂದ ಉಳಿದವನ್ನು ಕೇಳಲಿಲ್ಲ. ವಿರಾಮ ಮುಗಿದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "Contacts read from Zoho now: {0}": "ಈಗ Zoho ದಿಂದ ಓದಿದ ಸಂಪರ್ಕಗಳು: {0}",
  "With a number in Zoho: {0}": "Zoho ದಲ್ಲಿ ಸಂಖ್ಯೆ ಇರುವವು: {0}",
  "Without a number in Zoho: {0}": "Zoho ದಲ್ಲಿ ಸಂಖ್ಯೆ ಇಲ್ಲದವು: {0}",
  "Zoho could not be read for: {0}": "Zoho ದಿಂದ ಓದಲಾಗದವು: {0}",
  "Linked contacts with a number: {0} of {1}": "ಸಂಖ್ಯೆ ಇರುವ ಜೋಡಿತ ಸಂಪರ್ಕಗಳು: {1} ರಲ್ಲಿ {0}",
  "Not asked yet: {0}. Press the button again.": "ಇನ್ನೂ ಕೇಳದವು: {0}. ಬಟನ್ ಅನ್ನು ಮತ್ತೆ ಒತ್ತಿ.",
  "Every linked contact has been asked. Pressing again reads the oldest ones again.": "ಜೋಡಿಸಲಾದ ಎಲ್ಲ ಸಂಪರ್ಕಗಳನ್ನು ಕೇಳಲಾಗಿದೆ. ಮತ್ತೆ ಒತ್ತಿದರೆ ಅತ್ಯಂತ ಹಳೆಯವನ್ನು ಮತ್ತೆ ಓದಲಾಗುತ್ತದೆ.",
  "Zoho sent no numbers. Customer and Vendor Numbers may be off in Zoho Books (Settings > Preferences > Customers and Vendors: Enable Customer Number, Enable Vendor Number). Zoho cannot switch them off again once on, so the owner decides. After Zoho has numbered the existing contacts, press the button again.": "Zoho ಯಾವುದೇ ಸಂಖ್ಯೆ ಕಳುಹಿಸಲಿಲ್ಲ. Zoho Books ನಲ್ಲಿ ಗ್ರಾಹಕ ಮತ್ತು ಮಾರಾಟಗಾರ ಸಂಖ್ಯೆಗಳು ಆಫ್ ಆಗಿರಬಹುದು (Settings > Preferences > Customers and Vendors: Enable Customer Number, Enable Vendor Number). ಒಮ್ಮೆ ಆನ್ ಮಾಡಿದರೆ Zoho ಅವನ್ನು ಮತ್ತೆ ಆಫ್ ಮಾಡಲು ಬಿಡುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಮಾಲೀಕರು ನಿರ್ಧರಿಸಬೇಕು. Zoho ಈಗಿರುವ ಸಂಪರ್ಕಗಳಿಗೆ ಸಂಖ್ಯೆ ನೀಡಿದ ನಂತರ, ಬಟನ್ ಅನ್ನು ಮತ್ತೆ ಒತ್ತಿ.",
  // 13 Nov 2026: delete several at once, stock requirements (indents) and the order book, partner login email
  "Select all": "ಎಲ್ಲವನ್ನೂ ಆಯ್ಕೆಮಾಡಿ",
