  "Tick checkouts to delete several together": "ಹಲವನ್ನು ಒಟ್ಟಿಗೆ ಅಳಿಸಲು ಚೆಕ್‌ಔಟ್‌ಗಳನ್ನು ಟಿಕ್ ಮಾಡಿ",
  "Tick rejected or refunded UTRs to delete several together": "ಹಲವನ್ನು ಒಟ್ಟಿಗೆ ಅಳಿಸಲು ತಿರಸ್ಕರಿಸಿದ ಅಥವಾ ಮರುಪಾವತಿಸಿದ UTR ಗಳನ್ನು ಟಿಕ್ ಮಾಡಿ",
