  "Could not delete it": "ಅಳಿಸಲು ಆಗಲಿಲ್ಲ",
  "Delete 1 ended checkout?": "ಕೊನೆಗೊಂಡ 1 ಚೆಕ್‌ಔಟ್ ಅಳಿಸಬೇಕೆ?",
  "Delete {0} ended checkouts?": "ಕೊನೆಗೊಂಡ {0} ಚೆಕ್‌ಔಟ್‌ಗಳನ್ನು ಅಳಿಸಬೇಕೆ?",
  "Delete 1 UTR record?": "1 UTR ದಾಖಲೆ ಅಳಿಸಬೇಕೆ?",
