  // 13 Nov 2026: the godown location link and QR on invoices; channel partners confirm their godown's paid orders
  "Godown location link (Google Maps)": "ಗೋದಾಮಿನ ಸ್ಥಳದ ಲಿಂಕ್ (Google Maps)",
