  "Add the location link": "ಸ್ಥಳದ ಲಿಂಕ್ ಸೇರಿಸಿ",
  "The location link cannot have spaces. In Google Maps, open the godown, press Share, then Copy link, and paste it here.": "ಸ್ಥಳದ ಲಿಂಕ್‌ನಲ್ಲಿ ಖಾಲಿ ಜಾಗ ಇರಬಾರದು. Google Maps ನಲ್ಲಿ ಗೋದಾಮನ್ನು ತೆರೆಯಿರಿ, Share ಒತ್ತಿ, ನಂತರ Copy link ಒತ್ತಿ, ಇಲ್ಲಿ ಅಂಟಿಸಿ.",
  "The location link must start with https:// (in Google Maps: Share, then Copy link).": "ಸ್ಥಳದ ಲಿಂಕ್ https:// ನಿಂದ ಪ್ರಾರಂಭವಾಗಬೇಕು (Google Maps ನಲ್ಲಿ: Share, ನಂತರ Copy link).",
  "The location link is too long. In Google Maps, press Share, then Copy link, for a short link.": "ಸ್ಥಳದ ಲಿಂಕ್ ತುಂಬಾ ಉದ್ದವಾಗಿದೆ. ಚಿಕ್ಕ ಲಿಂಕ್‌ಗಾಗಿ Google Maps ನಲ್ಲಿ Share, ನಂತರ Copy link ಒತ್ತಿ.",
  "That is not a working link. In Google Maps, open the godown, press Share, then Copy link, and paste it here.": "ಅದು ಕೆಲಸ ಮಾಡುವ ಲಿಂಕ್ ಅಲ್ಲ. Google Maps ನಲ್ಲಿ ಗೋದಾಮನ್ನು ತೆರೆಯಿರಿ, Share ಒತ್ತಿ, ನಂತರ Copy link ಒತ್ತಿ, ಇಲ್ಲಿ ಅಂಟಿಸಿ.",
  "Orders to confirm": "ದೃಢೀಕರಿಸಬೇಕಾದ ಆರ್ಡರ್‌ಗಳು",
  "Paid orders of your godown wait here for you to confirm them, as our office does. Our office confirms every payment first. Once an order is confirmed, open its invoice here or under Customer invoices to view, print or download it.": "ನಿಮ್ಮ ಗೋದಾಮಿನ ಪಾವತಿಯಾದ ಆರ್ಡರ್‌ಗಳು, ನಮ್ಮ ಕಚೇರಿ ಮಾಡುವಂತೆಯೇ, ನೀವು ದೃಢೀಕರಿಸಲು ಇಲ್ಲಿ ಕಾಯುತ್ತವೆ. ಪ್ರತಿ ಪಾವತಿಯನ್ನು ಮೊದಲು ನಮ್ಮ ಕಚೇರಿ ದೃಢೀಕರಿಸುತ್ತದೆ. ಆರ್ಡರ್ ದೃಢಪಟ್ಟ ನಂತರ, ಅದರ ಇನ್‌ವಾಯ್ಸ್ ಅನ್ನು ನೋಡಲು, ಮುದ್ರಿಸಲು ಅಥವಾ ಡೌನ್‌ಲೋಡ್ ಮಾಡಲು ಇಲ್ಲಿ ಅಥವಾ ಗ್ರಾಹಕರ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ತೆರೆಯಿರಿ.",
  "No orders are waiting to be confirmed.": "ದೃಢೀಕರಣಕ್ಕಾಗಿ ಯಾವ ಆರ್ಡರ್‌ಗಳೂ ಕಾಯುತ್ತಿಲ್ಲ.",
  "Confirmed in the last 3 days": "ಕಳೆದ 3 ದಿನಗಳಲ್ಲಿ ದೃಢೀಕರಿಸಲಾಗಿದೆ",
  "Confirm order": "ಆರ್ಡರ್ ದೃಢೀಕರಿಸಿ",
