  "Paid in full. Confirm the order when you accept it.": "ಪೂರ್ಣ ಪಾವತಿಯಾಗಿದೆ. ನೀವು ಸ್ವೀಕರಿಸಿದಾಗ ಆರ್ಡರ್ ದೃಢೀಕರಿಸಿ.",
