  "Void in Zoho. Our office decides what happens to it.": "Zoho ದಲ್ಲಿ ರದ್ದಾಗಿದೆ (void). ಇದಕ್ಕೆ ಏನಾಗಬೇಕು ಎಂದು ನಮ್ಮ ಕಚೇರಿ ನಿರ್ಧರಿಸುತ್ತದೆ.",
