  "Zoho is making the tax invoice. Until then this opens as a proforma; refresh in a minute.": "Zoho ತೆರಿಗೆ ಇನ್‌ವಾಯ್ಸ್ ತಯಾರಿಸುತ್ತಿದೆ. ಅಲ್ಲಿಯವರೆಗೆ ಇದು ಪ್ರೊಫಾರ್ಮಾ ಆಗಿ ತೆರೆಯುತ್ತದೆ; ಒಂದು ನಿಮಿಷದಲ್ಲಿ ರಿಫ್ರೆಶ್ ಮಾಡಿ.",
