  "Only an active channel partner can confirm orders": "ಸಕ್ರಿಯ ಚಾನೆಲ್ ಪಾಲುದಾರರು ಮಾತ್ರ ಆರ್ಡರ್‌ಗಳನ್ನು ದೃಢೀಕರಿಸಬಹುದು",
